(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0028.js"] = [{"id":"poem-b6e64770fcd6d404746be030","title":"傀儡吟","author":"明皇帝","dynasty":"唐","verses":["刻木牵丝作老翁，鸡皮鹤发与真同。","须臾弄罢寂无事，还似人生一梦中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c7cf9007-f2af-4954-a355-045c9589a7a8","tags":[]},{"id":"poem-b6e6791583ea2ed52abc56f7","title":"游仙窟诗 游后园","author":"张文成","dynasty":"唐","verses":["昔时过小苑，今朝戏后园。","两岁梅花匝，三春柳色繁。","水明鱼影静，林翠鸟歌喧。","何须杏树岭，即是桃花源。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2eecc300-b3e9-4168-b8b3-27a6f6e3c54c","tags":[]},{"id":"poem-b6f4307c5dd9b9af428e62b7","title":"别朝祐","author":"赵文","dynasty":"宋","verses":["又与我友别，独与我子俱。","念彼归舟疾，眠食今何如。","愁怀不可遣，頼有床头书。","曲江江上人，摇舟来卖鱼。","亦有妻与子，一饱便有余。","我生不如子，多忧化其须。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b60158ef-8256-447f-8c00-b7f0e2b27cd6","tags":[]},{"id":"poem-b7119a41b1203bce6fe00d51","title":"咏史诗 夷陵","author":"胡曾","dynasty":"唐","verses":["夷陵城阙倚朝云，战败秦师纵火焚。","何事三千珠履客，不能西御武安君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1f797a4d-cb71-443e-80c7-ab7b7e894872","tags":[]},{"id":"poem-b714bcb9de85a21606f1b2db","title":"鹊桥仙·朱楼彩舫","author":"黄庭坚","dynasty":"宋","verses":["朱楼彩舫，浮瓜沈李，报答风光有处。","一年尊酒暂时同，别泪作、人间晓雨。","鸳鸯机综，能令侬巧，也待乘槎仙去。","若逢海上白头翁，共一访、痴牛呆女。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-669","tags":[]},{"id":"poem-b7181d6063bdceb155ba7546","title":"题画","author":"赵文","dynasty":"宋","verses":["云巢草虫十有七，我言蜂蚁非虫匹。","我见二虫常敬之，为有君臣天所秩。","江南此虫久已无，烦君翦取赠老夫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-2591a5f0-6e6e-4d5d-9369-0589e9819c57","tags":[]},{"id":"poem-b7234eb8f2c19bfda2d8fc83","title":"醉桃源・阮郎归·花枝破蕾柳梢青","author":"谢逸","dynasty":"宋","verses":["花枝破蕾柳梢青。","春寒拂面轻。","一眉新月影三星。","铜荷烛烬零。","低凤扇，袅霓旌。","珊珊环佩声。","坐间谁识许飞琼。","对郎仙骨清。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-651","tags":[]},{"id":"poem-b7237d7171907560fcf7519e","title":"山店","author":"卢纶","dynasty":"唐","verses":["登登山路行时尽，决决溪泉到处闻。","风动叶声山犬吠，一家松火隔秋云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-682673fa-3fe9-4902-bb0a-0588c23ec54e","tags":[]},{"id":"poem-b72a4e07ad39b158ee4fffe6","title":"许真君铁柱","author":"李翔","dynasty":"唐","verses":["恐老蛟重作患深[一]，独埋铁柱至如今。","根牢直下蟠江底，势壮长留镇郡心。","神鬼每闻趋夜后，风雷不敢犯塘阴。","无因更走横泉窟，压断祈精气永沉。","（[一]首句有误，疑当作「深恐老蛟重作患」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6c289403-1a7a-4999-abea-a2007d73c984","tags":[]},{"id":"poem-b72b94105120d309bdc393de","title":"水龙吟·碧山横绕清湖","author":"李祁","dynasty":"宋","verses":["碧山横绕清湖，茂林秀麓波光里。","南宫老大，西洲漂荡，危亭重倚。","雨步云行，饵风饮雾，平生游戏。","笑此中空洞，都无一物，有神妙、浩然气。","扫尽云南梦北，看三江五湖秋水。","狂歌两解，清尊一举，超然千里。","江汉苍茫，故人何处，山川良是。","待白苹露下，青天月上，约骑鲸起。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-609","tags":[]},{"id":"poem-b730d0a315aaa2ff9fc37941","title":"杯中鱼子","author":"释居简","dynasty":"宋","verses":["眇如丝粟便悠然，漥玉深中浅注泉。","再晕不知前夜月，才生便乐此中天。","群分自笑如儿戏，聚育谁偏得母怜。","罔罟不来斯可乐，洋洋何必泳长川。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8469895c-4a45-43c5-be64-d3756fdd5559","tags":[]},{"id":"poem-b7363143b4f014ac1175b33a","title":"秋胡行 其一","author":"曹操","dynasty":"汉","verses":["晨上散关山，此道当何难！","晨上散关山，此道当何难！","牛顿不起，车堕谷间。","坐磐石之上，弹五弦之琴。","作为清角韵，意中迷烦。","歌以言志，晨上散关山。","有何三老公，卒来在我旁？","有何三老公，卒来在我旁？","负揜被裘，似非恒人。","谓卿云何困苦以自怨，徨徨所欲，来到此间？","歌以言志，有何三老公？","我居昆仑山，所谓者真人。","我居昆仑山，所谓者真人。","道深有可得。","名山历观，遨游八极，枕石漱流饮泉。","沈吟不决，遂上升天。","歌以言志，我居昆仑山。","去去不可追，长恨相牵攀。","去去不可追，长恨相牵攀。","夜夜安得寐，惆怅以自怜。","正而不谲，辞赋依因。","经传所过，西来所传。","歌以言志，去去不可追。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-16","tags":[]},{"id":"poem-b74090f95911af5102a42f9b","title":"喜外弟卢纶见宿","author":"司空曙","dynasty":"唐","verses":["静夜四无邻，荒居旧业贫。","雨中黄叶树，灯下白头人。","以我独沈久，愧君相见频。","平生自有分，况是蔡家亲。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f0cd6afd-c89d-4fc3-b214-bcbf63042e8e","tags":["唐诗三百首","生活","五言律诗","年老"]},{"id":"poem-b743249f42b850346a4d1a4e","title":"满庭芳·晓色云开","author":"秦观","dynasty":"宋","verses":["晓色云开，春随人意，骤雨才过还晴。","古台芳榭，飞燕蹴红英。","舞困榆钱自落，秋千外、绿水桥平。","东风里，朱门映柳，低底按小秦筝。","多情。","行乐处，珠钿翠盖，玉辔红缨。","渐酒空金，花困蓬瀛。","豆蔻梢头旧恨，十年梦，屈指堪惊。","凭阑久，疏烟淡日，寂寞下芜城。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-70","tags":["宋词三百首"]},{"id":"poem-b7474b981651c142ee6b333d","title":"横吹曲辞 入塞曲 二","author":"沈彬","dynasty":"唐","verses":["苦战沙间卧箭痕，戍楼闲上望星文。","生希国泽分偏将，死夺河源荅圣君。","鸢覰败兵眠白草，马惊边鬼哭阴云。","功多地远无人纪，汉阁笙歌日又曛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-888fd3d3-d777-401d-8b4a-e94d3ab3607f","tags":[]},{"id":"poem-b747d31f6efaafcf89b5cf38","title":"江舍人宅筵上有妓唱和州韩舍人歌辞因以寄","author":"徐铉","dynasty":"宋","verses":["良宵丝竹偶成欢，中有佳人俯翠鬟。","白雪飘飖传乐府，阮郎憔悴在人间。","清风朗月长相忆，佩蕙纫兰早晚还。","深夜酒空筵欲散，向隅惆怅鬓堪斑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6727bb56-6ecc-4b49-9866-83a3a78cee33","tags":[]},{"id":"poem-b74ebbe405bcd4bba1cc72cc","title":"次韵士特见怀古风","author":"李纲","dynasty":"宋","verses":["遭遇登黄合，平生志寝丘。","燋头无寸效，失脚落遐陬。","一去苍龙阙，三惊白露秋。","贾生时欲恸，平子不胜愁。","鄂渚何曾到，兰江未许留。","孤城逾地角，绝岛在鼇头。","父子同双影，箪瓢付一舟。","飘零已知幸，奇绝敢言游。","望断归来鹤，情孚不下鸥。","波涛从汹涌，鼓角助清幽。","忽奉日边令，容还峤北州。","天恩方肉骨，厉鬼漫持矛。","力拯中兴业，深防不戴讐。","当车虽怒臂，见险莫扶辀。","往事追何及，来功勉或收。","舍垣宜葺补，风雨正飕飗。","离索何其久，吟哦谁与酬。","管宁终著帽，王粲且登楼。","阻绝江南信，淹留海上洲。","归心良耿耿，去路尚悠悠。","见说鲸奔网，仍传盗聚蟊。","不知供羽卫，今有几貔貅。","瓯越亦远矣，江淮已定不。","视天真懵懵，知命罢休休。","水有朝东性，嫠非恤纬忧。","吾徒强餐饭，肉食自深谋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-bf6de3cb-8a16-4293-97ae-ddd312937578","tags":[]},{"id":"poem-b75accf9bfdaa4a82c5a4a92","title":"忆金门旧游奉寄江西沈大夫","author":"李德裕","dynasty":"唐","verses":["东望沧溟路几重，无因白首更相逢。","已悲泉下双琪树，又惜天边一卧龙。","人事升沉才十载，宦游漂泊过千峰。","思君远寄西山药，岁暮相期向赤松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4cd93e8a-ad8d-43d9-8d71-72e69c5ba79f","tags":[]},{"id":"poem-b75c4431412da69827516b3f","title":"句","author":"王铉","dynasty":"唐","verses":["雨似随车至，云疑逐盖飞。","（〖1〗句次王坚诗句后，曰「文林郎王铉诗曰〖句不重录〗」云云。","按唐有两王铉，《全唐文》卷七九一收王铉文二篇，乃大中时处士，此则长安间人。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-97f46ccc-c62a-4af5-8bf3-157a4b8896f2","tags":[]},{"id":"poem-b75e5768ec364889e089796a","title":"答丁元珍","author":"欧阳修","dynasty":"宋","verses":["春风疑不到天涯，二月山城未见花。","残雪压枝犹有橘，冻雷惊笋欲抽芽。","夜闻啼雁生乡思，病入新年感物华。","曾是洛阳花下客，野芳虽晚不须嗟。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-答丁元珍","tags":[]},{"id":"poem-b767246689d34588b49a8fc2","title":"自湘乡趋邵阳以避谤不敢取道衡岳有感五首  其二","author":"李纲","dynasty":"宋","verses":["石廪巉天堆祝融，遥看山色有无中。","寛恩异日容归老，先到衡阳回鴈峰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c9ede289-cc8c-40c4-8f83-4fb773cfde7e","tags":[]},{"id":"poem-b76ff1a6fd113016365f3450","title":"将归蜀留献恩地仆射二首 二","author":"姚鹄","dynasty":"唐","verses":["江上长思狎钓翁，此心难与昨心同。","自承丘壑新恩重，已分烟霞旧隐空。","龙变偶因资巨浪，鸟飞谁肯借高风。","应怜死节无门効，永叹潜怀似转蓬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-35cf4d8e-6ecd-49fe-8a3a-d098f9f32bd9","tags":[]},{"id":"poem-b773a40cc3c37e151b6459a5","title":"送友人归山歌二首 一","author":"王维","dynasty":"唐","verses":["山寂寂兮无人，又苍苍兮多木。","群龙兮满朝，君何为兮空谷。","文寡和兮思深，道难知兮行独。","悦石上兮流泉，与松间兮草屋。","入云中兮养鸡，上山头兮抱犊。","神与枣兮如瓜，虎卖杏兮收谷。","愧不才兮妨贤，嫌既老兮贪禄。","誓解印兮相从，何詹尹兮何卜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-39096ae6-97b3-422e-a1c6-f725d8f5c105","tags":[]},{"id":"poem-b781d1185a5e1ab385b52267","title":"送契上人游扬州","author":"皎然","dynasty":"唐","verses":["西陵古江口，远见东扬州。","渌水不同泛，春山应独游。","寻僧白岩寺，望月谢家楼。","宿昔心期在，人寰非久留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-dbad6d4f-0e8c-4418-acd9-c215f801476a","tags":[]},{"id":"poem-b7886748288d11d2bbf53326","title":"吊元鲁山 十","author":"孟郊","dynasty":"唐","verses":["遗婴尽雏乳，何况骨肉枝。","心肠结苦诚，胸臆垂甘滋。","事已出古表，谁言独今奇。","贤人母万物，岂弟流前诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-390cd0ff-b216-4913-bb04-fa2efa555ba6","tags":[]},{"id":"poem-b78fab29ba1471d13935dfde","title":"句  其一二","author":"孟宾于","dynasty":"宋","verses":["吾祖并州隔万山，吾家多难谪郴连。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-851871db-3bb6-4adf-b4d3-6a0c0a1e96c6","tags":[]},{"id":"poem-b7a5b662483f7021f463a5fe","title":"酒泉子·日映纱窗","author":"温庭筠","dynasty":"唐","verses":["日映纱窗，金鸭小屏山碧。","故乡春，烟霭隔，背兰釭。","宿妆惆怅倚高阁，千里云影薄。","草初齐，花又落，燕双双。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-23","tags":[]},{"id":"poem-b7a9d69eba1ffa7ed3dc4fd9","title":"句  其二","author":"林栗","dynasty":"宋","verses":["千年依旧长安土，万里思归帝子家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b94c8d1b-1543-4396-9877-b9b02f408335","tags":[]},{"id":"poem-b7bc82ae9c72b8e8226e15ce","title":"江行无题一百首 六十","author":"钱珝","dynasty":"唐","verses":["景夕残霞落，秋寒细雨晴。","短缨何用濯，舟在月中行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7293bec0-5595-4fa1-b706-3a76dfbb596a","tags":[]},{"id":"poem-b7bce22ba20fe41354bcdf29","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(丑)刘姑夫听奴拜启，切莫要专心劳记。","儿夫性刚忒没礼，把闲事一笔勾除。","(合前。","净)切莫要与三姑娘得知。","(生)醉了，不吃了。","(净浑介)。","听我一言断送，须要勤耕苦种。","若不听我良言，各自寻条蛇弄。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8862","tags":[]},{"id":"poem-b7bec2ea0d45505a724edebf","title":"寄故人","author":"张籍","dynasty":"唐","verses":["静曲闲房病客居，蝉声满树槿花疎。","故人祗在蓝田县，强半年来未得书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0ec7646c-d08e-40af-8557-f9530dfacd43","tags":[]},{"id":"poem-b7c28064f48843c1f15e48b9","title":"江城子·碧栏干外小中庭","author":"张泌","dynasty":"五代","verses":["碧栏干外小中庭，雨初晴，晓莺声。","飞絮落花，时节近清明。","睡起卷帘无一事，匀面了，没心情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-0","tags":[]},{"id":"poem-b7c34f6c13ea09d790372641","title":"临江仙·点滴芭蕉心欲碎","author":"纳兰性德","dynasty":"清","verses":["点滴芭蕉心欲碎，声声催忆当初。","欲眠还展旧时书。","鸳鸯小字，犹记手生疏。","倦眼乍低缃帙乱，重看一半模糊。","幽窗冷雨一灯孤。","料应情尽，还道有情无。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-126","tags":[]},{"id":"poem-b7c4a796bdc6f31e4921d83e","title":"蝶恋花·又到绿杨曾折处","author":"纳兰性德","dynasty":"清","verses":["又到绿杨曾折处，不语垂鞭，踏遍清秋路。","衰草连天无意绪，雁声远向萧关去。","不恨天涯行役苦，只恨西风，吹梦成今古。","明日客程还几许，沾衣况是新寒雨。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-122","tags":[]},{"id":"poem-b7cbaf9548a5a9aa7222a89a","title":"玉台观","author":"高适","dynasty":"唐","verses":["浩劫因王造，平台访古游。","彩云萧史驻，文字鲁恭留。","宫阙通群帝，乾坤到十洲。","人传有笙鹤，时过北山头。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-玉臺觀","tags":[]},{"id":"poem-b7df0b70217a9760a73d5b80","title":"酒泉子·罗带惹香","author":"温庭筠","dynasty":"唐","verses":["罗带惹香，犹系别时红豆。","泪痕新，金缕旧，断离肠。","一双娇燕语雕梁，还是去年时节。","绿阴浓，芳草歇，柳花狂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-25","tags":[]},{"id":"poem-b7f0d85caaa43ca1f459115a","title":"子规","author":"项斯","dynasty":"唐","verses":["游魂自相叫，宁复记前身。","飞过人家月，声连客路春。","梦边催晓急，愁外送风频。","自有沾花血，相和泪滴新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-cd2a40ff-c1c2-47e8-9d2c-91e3a50fd579","tags":[]},{"id":"poem-b7f1092eaa458ba94f7fa09b","title":"诗一首","author":"张𬸦","dynasty":"唐","verses":["歛笑偷残靥，含羞露半唇。","一眉犹叵耐，双眼定伤人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3c4b8756-8e5c-4bdc-b90f-a8b4fcc5fd1a","tags":[]},{"id":"poem-b7f3112c9a20db319d0ba843","title":"诫贪","author":"子兰","dynasty":"唐","verses":["多求待心足，未足旋倾覆。","明知贪者心，求荣不求辱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5a4daf63-3283-4120-b40d-bcd25d7bd807","tags":[]},{"id":"poem-b7fa11ca845f52071bba2796","title":"别孙䜣","author":"高适","dynasty":"唐","verses":["离人去复留，白马黑貂裘。","屈指论前事，停鞭惜旧游。","帝乡那可忘，旅馆日堪愁。","谁念无知己，年年睢水流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2e65c105-017c-4b5c-b899-6ace25d18507","tags":[]},{"id":"poem-b80034325ecf41f4aa8c2002","title":"晨起","author":"曹松","dynasty":"唐","verses":["晓色教不睡，卷帘清气中。","林残数枝月，发冷一梳风。","竝鸟含钟语，欹荷隔雾空。","莫疑营白日，道路本无穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-37de8672-2d8c-47da-b724-7370f6380c8b","tags":[]},{"id":"poem-b80a676981d64a38c02014b6","title":"折杨柳","author":"郑愔","dynasty":"唐","verses":["青柳映红颜，黄云蔽紫关。","忽闻边使出，枝叶为君攀。","舞腰愁欲断，春心望不还。","风花滚成雪，罗绮乱斑斑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-de8e32f9-2b0c-48e2-89a6-7ef1db382ee2","tags":[]},{"id":"poem-b810f020ad9c7f1056e1366b","title":"将归故山留别杜侍御","author":"王建","dynasty":"唐","verses":["有川不得涉，有路不得行。","沈沈百忧中，一日如一生。","错来干诸侯，石田废春耕。","虎戟衞重门，何因达中诚。","日月俱照辉，山川异阴晴。","如何百里间，开目不见明。","我今归故山，誓与草木幷。","愿君去丘坂，长使道路平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9661054e-93f0-4f1b-bec0-0c83814e189d","tags":[]},{"id":"poem-b812589b797a6f900746d0cf","title":"诗酒六首  其三","author":"华镇","dynasty":"宋","verses":["辞宦各归千里外，满城不出数家中。","得诗夜共嘲骚客，次韵时来寄子翁。","已分鹭鸾垂翠葆，尚能鱼目鬭珠丛。","人生闲里还无此，白首光阴过莫空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1ac541b0-c1ad-4bc8-87cc-196d407796a5","tags":[]},{"id":"poem-b8130d4969321cf59cb9abdb","title":"还过东都留守周公筵上赠座客","author":"徐铉","dynasty":"宋","verses":["贾生三载在长沙，故友相思道路赊。","已分终年甘寂寞，岂知今日返京华。","麟符上相恩偏厚，隋苑留欢日欲斜。","明旦江头倍惆怅，远山芳草映残霞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4f0996b3-1ea5-444b-b2b4-777fa6d82f67","tags":[]},{"id":"poem-b81b8232f91448e263e16f21","title":"鹧鸪天·欲上南湖采舫嬉","author":"晁补之","dynasty":"宋","verses":["欲上南湖采舫嬉。","还思北渚与岚漪。","圆荷盖水垂杨暗，㶉𫛶鸳鸯总下时。","持此意，遣谁知。","清波还照鬓间丝。","西楼重唱池塘好，应有红妆敛翠眉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-231","tags":[]},{"id":"poem-b81c4be35840ab3c03e3bd9c","title":"帝京篇十首 五","author":"太宗皇帝","dynasty":"唐","verses":["芳辰追逸趣，禁苑信多奇。","桥形通汉上，峰势接云危。","烟霞交隐映，花鸟自参差。","何如肆辙迹？万里赏瑶池。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-86952cb3-b622-4398-a56a-01dd39f6c6ec","tags":[]},{"id":"poem-b820f2cabadb3a046f710028","title":"元祐辛未上元后一日同周文之刘瑞迈章纵矩游浮玉","author":"米芾","dynasty":"宋","verses":["近臈昔夹衣，入春今重裘。","天运亦已广，四序或不周。","张灯儿戏歇，发兴在沧洲。","兹山通玄府，瑶坛帝曾游。","荷衣可荐藻，神清不沉牛。","厌俗入喧乱，风波屡为忧。","昨夕浄名天，结客涌不留。","一唈寄心契，江澄客漾舟。","冰磴若见拒，寒荄如有愁。","大块欲动蛰，阴壑尚潜虬。","重赏定谁与，春光会和柔。","临旷摄北若，持坏结东流。","卧石带白云，勒崖托千秋。","焦公心赏佳，扫迹愿相投。","分山飞鸟争，划水游鳞雠。","借我一锡地，为公瓢挂头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b7d4821d-fab6-478c-803c-f3052027b2b9","tags":[]},{"id":"poem-b823b236c9406dd5c3b5e4e3","title":"凉州词三首 一","author":"张籍","dynasty":"唐","verses":["边城暮雨雁飞低，芦笋初生渐欲齐。","无数铃声遥过碛，应驮白练到安西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0d5cfc9c-9522-44de-9c4b-17c73394212a","tags":[]},{"id":"poem-b82b40ed1909fd623b2b3415","title":"水槛","author":"杜甫","dynasty":"唐","verses":["苍江多风飙，云雨昼夜飞。","茅轩驾巨浪，焉得不低垂。","游子久在外，门户无人持。","高岸尚如谷，何伤浮柱攲。","扶颠有劝诫，恐贻识者嗤。","既殊大厦倾，可以一木支。","临川视万里，何必阑槛为。","人生感故物，慷慨有余悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-be10e787-c739-44b9-a572-397e10138d0c","tags":[]},{"id":"poem-b82c6db7c355fe9d0f3f555d","title":"虞美人·银床淅沥青梧老","author":"纳兰性德","dynasty":"清","verses":["银床淅沥青梧老，屧粉秋蛩扫。","采香行处蹙连钱，拾得翠翘何恨不能言。","回廊一寸相思地，落月成孤倚。","背灯和月就花阴，已是十年踪迹十年心。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-157","tags":[]},{"id":"poem-b82d453678ffbb7848519806","title":"和韦相公见示闲卧","author":"贯休","dynasty":"唐","verses":["刻形求得相，事事未尝眠。","霖雨方为雨，非烟岂是烟。","童收庭树果，风曳案头牋。","仲虺专为诰，何充雅爱禅。","静嫌山色远，病是酒杯偏。","蜩响初穿壁，兰芽半出甎。","堂悬金粟像，门枕御沟泉。","旦沐虽频握，融帷孰敢褰。","德高群彦表，善植几生前。","修补乌皮几，深藏子敬毡。","扶持千载圣，潇洒一声蝉。","棋阵连残月，僧交似大颠。","常知生似幻，维重直如弦。","饼忆莼羹美，茶思岳瀑煎。","祗闻温树誉，堪鄙竹林贤。","脱颖三千士，馨香四十年。","宽平开义路，淡泞润清田。","哲后知如子，空王夙有缘。","对归香满袖，吟次月当川。","休说慙如揵，尧天即梵天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-82d82ab1-d18d-496b-b0f7-7931ce75bf6f","tags":[]},{"id":"poem-b83dae314a033e605ba625e2","title":"詶愿公雪中见寄","author":"卢仝","dynasty":"唐","verses":["积雪三十日，车马路不通。","贫病交亲绝，想忆唯愿公。","春鸠报春归，苦寒生暗风。","簷乳堕悬玉，日脚浮轻红。","梅柳意却活，园圃冰始融。","更候四体好，方可到寺中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c8cf8714-e532-4480-b383-40518617e24c","tags":[]},{"id":"poem-b848f92fcd4adf606821fb3e","title":"石鼓歌","author":"韩愈","dynasty":"唐","verses":["张生手持石鼓文，劝我试作石鼓歌。","少陵无人谪仙死，才薄将奈石鼓何。","周纲陵迟四海沸，宣王愤起挥天戈。","大开明堂受朝贺，诸侯劒佩鸣相磨。","搜于岐阳骋雄俊，万里禽兽皆遮罗。","镌功勒成告万世，凿石作鼓隳嵯峨。","从臣才艺咸第一，拣选撰刻留山阿。","雨淋日炙野火燎，鬼物守护烦㧑呵。","公从何处得纸本，毫发尽备无差讹。","辞严义密读难晓，字体不类隶与科。","年深岂免有缺画，快劒斫断生蛟鼍。","鸾翔凤翥众僊下，珊瑚碧树交枝柯。","金绳铁索锁纽壮，古鼎跃水龙腾梭。","陋儒编诗不收入，二雅褊迫无委蛇。","孔子西行不到秦，掎摭星宿遗羲娥。","嗟予好古生苦晚，对此涕泪双滂沱。","忆昔初蒙博士徴，其年始改称元和。","故人从军在右辅，为我度量掘臼科。","濯冠沐浴告祭酒，如此至宝存岂多。","氊包席裹可立致，十鼓祗载数骆驼。","荐诸太庙比郜鼎，光价岂止百倍过。","圣恩若许留太学，诸生讲解得切磋。","观经鸿都尚填咽，坐见举国来奔波。","剜苔剔藓露节角，安置妥帖平不颇。","大厦深簷与盖覆，经历久远期无佗。","中朝大官老于事，讵肯感激徒媕婀。","牧童敲火牛砺角，谁复著手为摩挲。","日销月铄就埋没，六年西顾空吟哦。","羲之俗书趁姿媚，数纸尚可博白鹅。","继周八代争战罢，无人收拾理则那。","方今太平日无事，柄任儒术崇丘轲。","安能以此上论列，愿借辨口如悬河。","石鼓之歌止于此，呜呼吾意其蹉跎。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1b9b8047-2410-47ae-a24c-aad7342b338f","tags":["唐诗三百首","七言古诗","题咏"]},{"id":"poem-b8583becdc7b4f0a567f7d6a","title":"胡蝶飞","author":"李贺","dynasty":"唐","verses":["杨花扑帐春云热，龟甲屏风醉眼缬。","东家胡蝶西家飞，白骑少年今日归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-97f0e647-3011-4b70-9741-2fbdbff85fdd","tags":[]},{"id":"poem-b8598ae428d0a6d4059d3f6b","title":"题王况故居","author":"刘言史","dynasty":"唐","verses":["入巷萧条起悲绪，儿女犹居旧贫处。","尘满空床屋见天，独作驴鸣一声去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e6e58e70-d76d-4bcf-adee-3e7506f01256","tags":[]},{"id":"poem-b85a22f273ade021f7c6f420","title":"逢归信偶寄","author":"李益","dynasty":"唐","verses":["无事将心寄柳条，等闲书字满芭蕉。","乡关若有东流信，遣送扬州近驿桥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ed7f860f-572b-468f-a70a-d6b233f0cbc6","tags":[]},{"id":"poem-b85e3b98400eb6f9ccda4cba","title":"延英殿玉灵芝诗三章章八句 二","author":"肃宗皇帝","dynasty":"唐","verses":["元气产芝，明神合德。","紫微间采，白蕣呈色。","载启瑞图，庶符皇极。","天心有眷，王道惟直。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-247aeb58-ca1c-46e4-8bf3-81c400f0ec8a","tags":[]},{"id":"poem-b8616fa26fffa5591ec36952","title":"赠别二首 二","author":"杜牧","dynasty":"唐","verses":["多情却似总无情，唯觉尊前笑不成。","蜡烛有心还惜别，替人垂泪到天明。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a7f425de-143b-493d-bb51-13e27c68e871","tags":["唐诗三百首","离别","七言绝句","惜别"]},{"id":"poem-b862f53094928ae7f07ab428","title":"仲春有怀  其一","author":"张栻","dynasty":"宋","verses":["青山四面拥江城，暮角声中淡月明。","自倚阑干生白发，无心行乐趁春晴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a62a0f28-7c36-4aa1-8bdc-e9b661f3a549","tags":[]},{"id":"poem-b863584d95999cee40ca320b","title":"宿云际寺赠深上人","author":"李端","dynasty":"唐","verses":["暂别青蓝寺，今来发欲斑。","独眠孤烛下，风雨在前山。","坏宅终须去，空门不易还。","支公有方便，一愿启玄关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c90872e4-378a-48f6-b5dd-3ddf44f4af01","tags":[]},{"id":"poem-b86369dba5cfffe164b4ad0e","title":"和段相公登武担寺西台","author":"杨汝士","dynasty":"唐","verses":["清净此道宫，层台复倚空。","偶时三伏外，列席九霄中。","平视云端路，高临树杪风。","自怜荣末座，前日别池笼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-743b1a3c-e602-4604-a181-317bd81e60d0","tags":[]},{"id":"poem-b868968c912fd857fc1b3726","title":"奉和杨驸马六郎秋夜即事","author":"王维","dynasty":"唐","verses":["高楼月似霜，秋夜郁金堂。","对坐弹卢女，同看舞凤凰。","少儿多送酒，小玉更焚香。","结束平阳骑，明朝入建章。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6688fe24-3774-4619-90c3-53f950a45bc7","tags":[]},{"id":"poem-b86b91790447340497aa5ec5","title":"蓟门行五首 一","author":"高适","dynasty":"唐","verses":["蓟门逢古老，独立思氛氲。","一身既零丁，头鬓白纷纷。","勋庸今已矣，不识霍将军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b44f7786-9795-41c3-b69e-cee35d6154b9","tags":[]},{"id":"poem-b86d7d687c4c627c65fd0621","title":"傍妆台","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［老旦］意悬悬，倚门终日，望得眼儿穿。","自他去京历鏖战，无一纸信音传。","［旦］多应他在京得中选，因此上无暇修书寄故园。","［老旦］他既登金榜，怎不锦旋，越教娘心下转萦牵。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8173","tags":[]},{"id":"poem-b86fe0d960a981d01665406d","title":"捣练子令·深院静","author":"李煜","dynasty":"五代","verses":["深院静，小庭空，断续寒砧断续风。","无奈夜长人不寐，数声和月到帘栊。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-18","tags":[]},{"id":"poem-b8707674b9158dec589df98c","title":"横吹曲辞 折杨柳","author":"沈佺期","dynasty":"唐","verses":["玉窗朝日映，罗帐春风吹。","拭泪攀杨柳，长条宛地垂。","白花飞历乱，黄鸟思参差。","妾自肝肠断，旁人那得知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-34bac317-4e11-40fa-abae-731bfb0e8d9c","tags":[]},{"id":"poem-b87b10f9e62c2607c347c107","title":"公䜩诗","author":"罗绍威","dynasty":"唐","verses":["帘前淡泊云头日，座上萧骚两脚风。","（见《吟窗杂录》卷二五《历代吟谱》。","）（按：《全唐诗》卷七三四收二句，缺题，今重录。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-78a05b7b-7b32-47e9-9b5d-73624d6edf1d","tags":[]},{"id":"poem-b87ba23bb79f30ca12f0fc55","title":"夜上隐居寺","author":"唐求","dynasty":"唐","verses":["寻师拟学空，空住虎磎东。","千里照山月，一枝惊鹤风。","年如流去水，山似转来蓬。","尽日都无事，安禅石窟中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6b9648ad-db50-4e4d-a427-fe43c1362e88","tags":[]},{"id":"poem-b87eeb002f71929ac7afb67a","title":"赠送郑钱二郎中","author":"司空曙","dynasty":"唐","verses":["梅含柳已动，昨日起东风。","惆怅心徒壮，无如鬓作翁。","百年飘若水，万绪尽归空。","何可宗禅客，迟回岐路中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-19eabf31-3e26-479c-a0d1-1345d86cca1d","tags":[]},{"id":"poem-b88099d2683c25a03d68aef1","title":"菩萨蛮·砑笺银粉残煤画","author":"纳兰性德","dynasty":"清","verses":["砑笺银粉残煤画，画煤残粉银笺砑。","清夜一灯明，明灯一夜清。","片花惊宿燕，燕宿惊花片。","亲自梦归人，人归梦自亲。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-193","tags":[]},{"id":"poem-b8938c898c5a053b04c1ea23","title":"暗用古人名诗寄程帅","author":"陈造","dynasty":"宋","verses":["羡公椽笔衔阳秋，黄钟大吕豪端收。","省闱高掇未足道，文章老手第一流。","𫐖轕玄谭已惊众，倒河翻澜骇飞动。","递中筒诗陆续来，旧债未偿新债重。","即今搦管重犯严，强颜回顾口如箝。","更驱行李伸此情，句法政用公镌劖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-14ea4512-bd6b-468e-ad5b-3ef4b332a9bf","tags":[]},{"id":"poem-b89d758aaebf86f32d367021","title":"甘州子·每逢清夜与良晨","author":"顾敻","dynasty":"五代","verses":["每逢清夜与良晨，多怅望，足伤神。","云迷水隔意中人，寂寞绣罗茵。","山枕上，几点泪痕新。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-42","tags":[]},{"id":"poem-b8a19575cc3a7fb2d1406319","title":"谒金门·伤离索","author":"毛并","dynasty":"宋","verses":["伤离索。","犹记并肩池阁。","病起绿窗闲倚薄。","一秋天气恶。","玉臂都宽金约。","歌舞新来忘却。","回首故人天一角。","半江枫又落。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-634","tags":[]},{"id":"poem-b8a859d48254aad1692438e2","title":"吴江长桥","author":"刘跂","dynasty":"宋","verses":["路隔银潢鸟倦飞，行人恐犯女星机。","长虹出浪无冬夏，老蜃浮空半是非。","两岸履声云内合，三州帆影月边归。","栏干独立秋风早，岂待鲈鱼始拂衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-759b6f6c-c8d7-4113-a7ea-b869800d24c4","tags":[]},{"id":"poem-b8b42e922576f8481daf7380","title":"樵谷","author":"释居简","dynasty":"宋","verses":["谷口云横草不生，弗容斤斧弗容耕。","呼童尽拾风前叶，自去提撕折脚铛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-382c9b4e-61dc-4691-bd78-3fffd4ffec6d","tags":[]},{"id":"poem-b8b9b5d3bcf433872095633f","title":"奉和圣制幸韦嗣立山庄应制","author":"赵彦昭","dynasty":"唐","verses":["廊庙心存岩壑中，銮舆瞩在灞城东。","逍遥自在蒙庄子，汉主徒言河上公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e7ba1af6-b990-4faa-aacd-7bfdce317f98","tags":[]},{"id":"poem-b8bfc126ab1ee08b113163a0","title":"句","author":"孙谔","dynasty":"宋","verses":["秋空独见周王庙，夜月犹悬蜀将营。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-89ab5aaf-ff57-496d-9157-e7d3190b2a04","tags":[]},{"id":"poem-b8c8a4e4e628a9ed34ab876d","title":"泂酌","author":"佚名","dynasty":"先秦","verses":["泂酌彼行潦，挹彼注兹，可以餴饎。岂弟君子，民之父母。","泂酌彼行潦，挹彼注兹，可以濯罍。岂弟君子，民之攸归。","泂酌彼行潦，挹彼注兹，可以濯溉。岂弟君子，民之攸墍。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-250","tags":[]},{"id":"poem-b8d33dab0dba2eb30e0cb5ee","title":"李才翁懒窝  其七","author":"林宪","dynasty":"宋","verses":["月华浴沆瀣，天容注琉璃。","皎如大圆镜，照彻清境晖。","繁星歛芒曜，群动生霏微。","尘世宁有此，玉虚楼观低。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-fa218170-348c-4979-ae75-b15a0261b0cf","tags":[]},{"id":"poem-b8d461aa7febf47b0b271263","title":"寄严文炳  其四","author":"陈造","dynasty":"宋","verses":["乌墅两冯君，风霆蔼休问。","自昔从之游，诗力借余润。","夫君凛一敌，鸿笔上群俊。","旧坛今寻盟，得句毋我靳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-65ed158e-893a-48e7-80da-0358153d028b","tags":[]},{"id":"poem-b8d8c4cb418b5738275e9d89","title":"大圣乐","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["婚姻事难论高低，论高低何如休嫁与。","假如亲贱孩儿贵，终不然便抛弃？(外)他的孩儿撇不得，你怕甚么？(贴)奴是他亲生儿子亲媳妇，难道他是何人我是谁？(外)你怎地只管把言语来冲撞我？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5178","tags":[]},{"id":"poem-b8dad657de90c5a19cfc4f6e","title":"游仙词三十三首  其一八","author":"王镃","dynasty":"宋","verses":["看了金书看水流，刚风吹鬓不知秋。","碧瞳仙过天河去，戏擘云衣作彩舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c69f67ab-64ad-453d-8bbf-a8f7decabbf7","tags":[]},{"id":"poem-b8dcf15fc07ae5878b725442","title":"太傅相公以梅圣俞寄和建茶诗垂示俾次前韵","author":"苏颂","dynasty":"宋","verses":["近来不贵蜀吴茶，为有东溪早露芽。","二月制成输御府，经时犹未到人家。","太官供罢颁三吏，东合开时咏九华。","从此闽乡益珍尚，佳章奇品两相夸。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0e9fc78e-ef60-44e3-85b5-bc5ecfd4074e","tags":[]},{"id":"poem-b8deed4bfdc3ef8c2f9bc626","title":"早春书怀寄李少府仲宣","author":"皎然","dynasty":"唐","verses":["早年初问法，因悟目中花。","忽值胡雏起，芟夷如乱麻。","脱身投彼岸，吊影念生涯。","迹与空门合，心将世路赊。","东田已芜没，南涧益伤嗟。","崇替惊人事，凋残感物华。","知君过我里，惆怅旧烟霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4b4fd7a6-139e-49f3-b28a-e5eb3ffe497f","tags":[]},{"id":"poem-b8e4b3d76ad1acce95c10f40","title":"古风二首 一","author":"李绅","dynasty":"唐","verses":["春种一粒粟，秋成万颗子。","四海无闲田，农夫犹饿死。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-04970036-9dd8-4ad6-9193-4ac9731ad381","tags":[]},{"id":"poem-b8e7847757c2a07b863e180a","title":"菩萨蛮·朔风吹散三更雪","author":"纳兰性德","dynasty":"清","verses":["朔风吹散三更雪，倩魂犹恋桃花月。","梦好莫催醒，由他好处行。","无端听画角，枕畔红冰薄。","塞马一声嘶，残星拂大旗。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-105","tags":[]},{"id":"poem-b8e79ffd9d037f1ed8ab041b","title":"郊庙歌辞 祭方丘乐章 顺和","author":"不详","dynasty":"唐","verses":["坤厚载物，德柔垂祉。","九域咸雍，四溟为纪。","敬因良节，虔修阴祀。","广乐式张，灵其降止。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a5616d09-2763-4ec5-9f72-1eb3992c6bff","tags":[]},{"id":"poem-b8edb5e20e7aa89f17c93bca","title":"立秋后题","author":"杜甫","dynasty":"唐","verses":["日月不相饶，节序昨夜隔。","玄蝉无停号，秋燕已如客。","平生独往愿，惆怅年半百。","罢官亦由人，何事拘形役。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e8e50fc9-2d2d-4f48-9fe4-2be2d4afad73","tags":[]},{"id":"poem-b8fde3d3c7a2d34dabed229b","title":"所寓天宁方丈后有阇提花数株连月盛开玉雪可爱怅然有怀成三绝句寄吴元中  其二","author":"李纲","dynasty":"宋","verses":["深院无人帘幕垂，玉英翠羽灿芳枝。","世间颜色难相似，晴雪初残未堕时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-aa7d7816-d98d-46cc-a61f-9cc66182cd34","tags":[]},{"id":"poem-b90d3fcd0aa3824457c0b496","title":"送贯微归天台","author":"秀登","dynasty":"唐","verses":["秋归赤城寺，幽兴唯相同。","迹与片云合，心向万境空。","倾耳霜树猿，吹衣瀑布风。","后夜越溪上，梦断寒猿中。","（《增广圣宋高僧诗选后集》卷上。","）（按：秀登事迹无考。","小白为唐僧，《全唐诗续补遗》收其诗三首；贯微为齐己之友，《白莲集》中有《荆门病中寄怀贯微上人》、《拟嵇康绝交寄湘中贯微》〖均卷四〗、《谢贯微上人寄示古风今体四轴》〖卷七〗、《荆川寄贯微上人》〖卷八〗、《寄武陵贯微上人二首》〖卷九〗等诗。","知秀登与齐己同时，为五代时人。","《宋诗纪事》卷九一收入，无事迹，似误。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a8801dfd-b58d-435c-8ce2-4d8be46c4f3e","tags":[]},{"id":"poem-b915e5ecb861c6fdcb6735d5","title":"石鱼湖上醉歌","author":"元结","dynasty":"唐","verses":["石鱼湖，似洞庭，夏水欲满君山青。","山为樽，水为沼，酒徒历历坐洲岛。","长风连日作大浪，不能废人运酒舫。","我持长瓢坐巴丘，酌饮四坐以散愁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8af643c9-a8b0-49b7-b8e9-88920ab0bbd8","tags":["唐诗三百首","洞庭湖"]},{"id":"poem-b91999fe46cdc5b2383e3dba","title":"次韵梁教章宰喜雪  其三","author":"陈造","dynasty":"宋","verses":["平时豪饮兴，人议老羌渴。","骏蹄就康庄，中有谿涧遏。","俛仰三十年，仅作扶病活。","乐事生无几，造物忍见夺。","谢安晚多感，正頼箫鼓聒。","胡姬卖酒地，缅想不容谒。","即今少年梦，尚苦法士孽。","两君诗酒豪，将坛最阀阅。","左顾得投辖，胜谭看吐屑。","雪天仆为更，盘饭鲜粗割。","共怜后山穷，块处但禅说。","一饱共此客，矜向邻里说。","问疾不厌频，他费尚可节。","官涂计离合，江海浮一叶。","别期后归燕，光阴等消雪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2fe0c7a5-47db-4f1a-8fa0-dcf0da566603","tags":[]},{"id":"poem-b9258da22535353d9154014d","title":"浪淘沙·望海","author":"纳兰性德","dynasty":"清","verses":["蜃阙半模糊，踏浪惊呼。","任将蠡测笑江湖。","沐日光华还浴月，我欲乘桴。","钓得六鳌无。","竿拂珊瑚。","桑田清浅问麻姑。","水气浮天天接水，那是蓬壶。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-120","tags":[]},{"id":"poem-b92618acd1d8552889876a1d","title":"剔银灯","author":"刘唐卿《白兔记》","dynasty":"元","verses":["闲时节三言两语，从今后一笔勾除。","郎争舅子因合理，从此后一团和气。","(合)一杯冲破了是非，今晚向瓜园中调理。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8860","tags":[]},{"id":"poem-b928c813a5a3c7b2fecc418b","title":"颂古十九首  其二","author":"释法全","dynasty":"宋","verses":["布鼓当轩为击来，卧龙惊起出岩隈。","千峰秀色凭谁写，一带澄江古镜开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-20ce74b3-136b-4618-9249-c9a499f0bf2e","tags":[]},{"id":"poem-b92fdd84e20bffaeabdb2601","title":"杨子津","author":"卢仝","dynasty":"唐","verses":["风卷鱼龙暗楚关，白波沈却海门山。","鹏腾鼇倒且快性，地坼天开总是闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fcd6c448-bd3c-43dd-bdde-066f63af4013","tags":[]},{"id":"poem-b932e490ffb36e88098cda19","title":"郊庙歌辞 武后崇先庙乐章","author":"不详","dynasty":"唐","verses":["先德谦㧑冠昔，严规节素超今。","奉国忠诚每竭，承家至孝纯深。","追崇惧乖尊意，显号恐玷徽音。","既迫王公屡请，方乃俯遂群心。","有限无由展敬，奠醑每阙亲斟。","大礼虔申典册，苹藻敬荐翘襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0cb1c0b0-5d86-4916-8d89-6ff586e84308","tags":[]},{"id":"poem-b93b869344f0c2050f88006c","title":"兵要望江南 《周易》占候第二十六（三十七首） 十二","author":"易静","dynasty":"唐","verses":["占贼信，鬼发内三中。","或是官爻生有气，贼军来速在逡巡，急备点三军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-398e0dca-8385-4023-ac6a-69c76392da6a","tags":[]},{"id":"poem-b93d9dd12f6245a1a99873df","title":"姑熟杂咏 牛渚矶","author":"李赤","dynasty":"唐","verses":["绝壁临巨川，连峰势相向。","乱石流洑间，回波自成浪。","但惊群木秀，莫测精灵状。","更听猨夜啼，忧心醉江上。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7e4e03c2-33b9-4cdd-8c8c-a5a7ec0d10e8","tags":[]},{"id":"poem-b93de4d43a4e0cb6cbeb71e6","title":"东风解冻省试","author":"徐夤","dynasty":"唐","verses":["暖气飘苹末，冻痕销水中。","扇冰初觉泮，吹海旋成空。","入律三春照，朝宗万里通。","岸分天影阔，色照日光融。","波起轻摇绿，鳞游乍跃红。","殷勤排弱羽，飞翥趂和风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4ed3fb07-b56a-44d5-ab3e-a53ace3f1316","tags":[]},{"id":"poem-b9433dce379accee8c0545cf","title":"碧衔霞行","author":"释居简","dynasty":"宋","verses":["双衔金勒明霞碧，暗花隠起云如刺。","霜零燕涧草根甜，长鸣振鬣飞无迹。","一朝群空十二闲，在图八骏亦腼颜。","乡令生并人间世，踯躅吞声敢伸喙。","真人开国宗承祖，犹有幽燕两抔土。","要须马上驾群雄，九重跨出苍玉虹。","短鞚长驱当峻坂，却后伸前如履坦。","紫驼峰荐碧琳腴，余沥娄分明玉瓒。","圉人太仆不敢侮，爪剔爬搔谨程度。","屹立亭亭时却顾，趯啮谁能犯其怒。","乡闻天马曾作歌，大宛西极都搜罗。","凤膺龙脊非凡驷，马肝遂误文成死。","遂使刘郎葬茂陵，不到昆台十二层。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-99e7ba4d-99da-4c33-811c-e7decc15d3d6","tags":[]},{"id":"poem-b9438815019f0e4fd63539d3","title":"相见欢·罗襦绣袂香红","author":"薛昭蕴","dynasty":"五代","verses":["罗襦绣袂香红，画堂中。","细草平沙番马，小屏风。","卷罗幕，凭妆阁，思无穷。","暮雨轻烟魂断，隔帘栊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-40","tags":[]},{"id":"poem-b943fc0ef0bbf09767208d8f","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["赵解重围魏再昌，信陵贤德日馨芳。","昏蒙愚主听谗说，公子云亡国亦亡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ceac5da1-4c73-4680-af3b-ab98521efb3d","tags":[]},{"id":"poem-b947cea1d4dad37ee5384b00","title":"赠三惠大师","author":"李洞","dynasty":"唐","verses":["枫猿峤角别多时，二教兼修内学师。","药树影中频缀偈，莲峰朵下几窥棋。","游归笋长齐童子，病起巢成露鹤儿。","诏落五天开夏讲，两街人竞礼长眉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2db05d4a-a627-4bbd-b852-c3e8a94bbfce","tags":[]},{"id":"poem-b9522d2089456d955198c3d2","title":"萧闲堂诗","author":"米芾","dynasty":"宋","verses":["谁起萧闲堂，图赞凡丑质。","昧昧起我思，有怀斯士吉。","吾生终不逢，二陵已相失。","苟养走四方，公卿更绝迹。","向老交渐稀，背憎十六七。","丰吾九畹兰，任汝满地棘。","我岂萧闲人，偶然得空壁。","美哉何方彦，精绝入妙笔。","君不愧顾长康，取媚桓温图九锡。","我不愧孟浩然，缓策京山遇摩诘。","前此交道久不康，纷纷白头多不卒。","呜呼纷纷白头多不卒，回首此君应辟易。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9dccc23d-7b52-4d17-b2e8-d10dde5023d2","tags":[]},{"id":"poem-b95abbc78133461f3f71e191","title":"丰年","author":"佚名","dynasty":"先秦","verses":["丰年多黍多稌，亦有高廪，万亿及秭。为酒为醴，烝畀祖妣。以洽百礼，降福孔皆。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-278","tags":[]},{"id":"poem-b965c36b11c046ddf4de1eaf","title":"句","author":"杨虞卿","dynasty":"唐","verses":["河势昆仑远，山形菡萏秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ebfb90a0-ccf4-4f10-bfe4-b8b1d253edf6","tags":[]},{"id":"poem-b967f6cb1646535a901b9e4f","title":"偈颂十二首  其四","author":"释原妙","dynasty":"宋","verses":["东西十万，南北八千。","纤尘不立，寸草不生。","往来无碍，妙用纵横。","直饶亲到者里，正是弃本逐末，引祸招殃。","且道如何是本，抛出轮王三寸铁，分明遍界是刀鎗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-228aabeb-5c3e-4f2e-81f7-3ef6a3a6e7b4","tags":[]},{"id":"poem-b971e609453f9ea3f541fceb","title":"题缑山王子晋庙","author":"郑畋","dynasty":"唐","verses":["有昔灵王子，吹笙溯泬㵳。","六宫攀不住，三岛去相招。","亡国原陵古，宾天岁月遥。","无蹊窥海曲，有庙访山椒。","石帐龙蛇拱，云栊彩翠销。","露坛装琬琰，真像写松乔。","珠馆青童宴，琳宫阿母朝。","气舆仙女侍，天马吏兵调。","湘妓红丝瑟，秦郎白管箫。","西城要绰约，南岳命娇娆。","句曲觞金洞，天台啸石桥。","晚花珠弄蘂，春茹玉生苗。","二景神光秘，三元宝箓饶。","雾垂鸦翅发，冰束虎章腰。","鹤驭争衔箭，龙妃合献绡。","衣从星渚浣，丹就日宫烧。","物外花尝满，人间叶自凋。","望台悲汉戾，阅水笑梁昭。","古殿香残炧，荒堦柳长条。","几曾期七日，无复降重霄。","嵩岭连天汉，伊澜入海潮。","何由得真诀，使我珮环飘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f3a62c39-2698-4d68-842f-a9ff595faa85","tags":["衡山"]},{"id":"poem-b975c5109e440dd1030e0aa2","title":"郊庙歌辞 祭方丘乐章 顺和","author":"褚亮","dynasty":"唐","verses":["阴祇协赞，厚载方贞。","牲币具举，箫管备成。","其礼惟肃，其德惟明。","神之听矣，式鉴虔诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-98035eea-d155-46b8-aca0-45c7a343993c","tags":[]},{"id":"poem-b983458e94efe1ba30932535","title":"拟古","author":"龚霖","dynasty":"唐","verses":["凉风摇翠袂，倚槛恨难平。","远路人无信，西楼月又生。","菱花消旧态，瑶瑟续新声。","暗觉新声苦，夫谁知此情？","（同前第六册第三八九七页）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-954cae91-578d-4641-9c2b-064d019836c9","tags":[]},{"id":"poem-b9868822bac7b633dcc9529f","title":"博头钱","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生)你好忒胡逞！你好不本分！教我争，你有何安稳？(净、丑)不听道，忒煞村！不依教，该受贫。","(外)算来贫富是前因，皆由命岂由人！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1827","tags":[]},{"id":"poem-b98c45a85c02cd17d4147d0f","title":"隋堤柳","author":"李山甫","dynasty":"唐","verses":["曾傍龙舟拂翠华，至今凝恨倚天涯。","但经春色还秋色，不觉杨家是李家。","背日古阴从北朽，逐波疎影向南斜。","年年只有晴风便，遥为雷塘送雪花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-72f577cd-8974-4e77-810b-731a0c7d5e2c","tags":[]},{"id":"poem-b992ecdb0f93cc1e923b262b","title":"河传·同伴","author":"温庭筠","dynasty":"唐","verses":["同伴，相唤。","杏花稀，梦里每愁依违。","仙客一去燕已飞，不归，泪痕空满衣。","天际云鸟引晴远，春已晚，烟霭渡南苑。","雪梅香，柳带长，小娘，转令人意伤。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-10","tags":[]},{"id":"poem-b998c2046aa66bd9d8c8a9cf","title":"上巳日陪齐相公花楼宴","author":"卢纶","dynasty":"唐","verses":["钟陵暮春月，飞观延群英。","晨霞耀中轩，满席罗金琼。","持杯凝远睇，触物结幽情。","树色参差绿，湖光潋滟明。","礼卑瞻绛帐，恩浃厕华缨。","徒记山阴兴，祓禊乃为荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d8592aae-e77c-4393-91b5-30a4db50c8e3","tags":[]},{"id":"poem-b99c154ce758b79bb86a22c7","title":"同李太守登历下古城员外新亭亭对鹊湖","author":"杜甫","dynasty":"唐","verses":["新亭结搆罢，隐见清湖阴。","迹籍台观旧，气溟海岳深。","圆荷想自昔，遗堞感至今。","芳宴此时具，哀丝千古心。","主称寿尊客，筵秩宴北林。","不阻蓬荜兴，得兼梁甫吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9a2c1932-4219-483b-a14b-52dc7265f6fb","tags":[]},{"id":"poem-b9a9d6c3a9a15ebdcba4eda8","title":"前曲","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["你儿夫曾付托，我怎生违背？你无钱使用，我须当代。","交你把头发剪了，又跌倒在长街，都缘是我之罪。","(合)叹一家破坏，否极何时泰来？各出着泪。","(旦唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5127","tags":[]},{"id":"poem-b9ac107ee07e0b9e525831e4","title":"拟古·予生未三十","author":"纳兰性德","dynasty":"清","verses":["予生未三十，忧愁居其半。","心事如落花，春风吹已断。","行当适远道，作记殊汗漫。","寒食青草多，薄暮烟冥冥。","山桃一夜红，茵箔随飘零。","愿餐玉红草，一醉不复醒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-250","tags":[]},{"id":"poem-b9ae4212e3ef06558c684704","title":"再和","author":"苏颂","dynasty":"宋","verses":["朱门罗绮竞珊珊，未必儒官偏少欢。","随分管弦娱性尚，等闲唱咏过暄寒。","幽人栖遁心非适，夸者经营席靡安。","一絓利名均是徇，能遗斯事更为难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8dd866ea-40eb-48fa-b393-926e8c66287d","tags":[]},{"id":"poem-b9b0cb86ec6f7e7cf3e633da","title":"赴南中留别褚七少府湖上林亭","author":"李嘉祐","dynasty":"唐","verses":["种田东郭傍春陂，万事无情把钓丝。","绿竹放侵行迳里，青山常对卷帘时。","纷纷花发门空闭，寂寂莺啼日更迟。","从此别君千万里，白云流水忆佳期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a8b615ec-00f5-4b3c-bcb7-8435e10014aa","tags":[]},{"id":"poem-b9b1f55b96b3fd15deea0eba","title":"送西川杜司空赴镇","author":"薛逢","dynasty":"唐","verses":["黑眉玄髪尚依然，紫绶金章五十年。","三入凤池操国柄，八分龙节付兵权。","东周城阙中天外，西蜀楼台落日边。","莫遣洪罏旷真宰，九流人物待陶甄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7d0b8eb1-c46c-4712-a990-58dac6e315aa","tags":[]},{"id":"poem-b9b3439b7ca9eae9b1242a13","title":"途中","author":"赵嘏","dynasty":"唐","verses":["故园回首雁初来，马上千愁付一杯。","惟有新诗似相识，暮山吟处共徘徊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-63b4fd17-3860-4666-8aa2-e0e8e4697298","tags":[]},{"id":"poem-b9b363f52c6c071698ef5e9a","title":"送綦毋潜落第还乡","author":"王维","dynasty":"唐","verses":["圣代无隐者，英灵尽来归。","遂令东山客，不得顾采薇。","既至君门远，孰云吾道非。","江淮度寒食，京洛缝春衣。","置酒临长道，同心与我违。","行当浮桂櫂，未几拂荆扉。","远树带行客，孤村当落晖。","吾谋适不用，勿谓知音稀。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-56bec3c2-9c0c-4d40-9750-2e28bdc9a20e","tags":["唐诗三百首","送别","五言古诗","慰勉","友情"]},{"id":"poem-b9b5813eae3d7f8ab0f48b69","title":"题终南山隐者居","author":"姚鹄","dynasty":"唐","verses":["开门绝壑旁，蹑藓过花梁。","路入峰峦影，风来芝术香。","夜吟明雪牖，春梦闭云房。","尽室更何有，一琴兼一觞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-77e275cf-2879-446f-92a4-4a57e69f819a","tags":["终南山"]},{"id":"poem-b9bb2533f5492e7d0d2566ea","title":"偈","author":"重恽","dynasty":"唐","verses":["云幽一只箭，虚空无背面。","射去遍十方，要且无人见。","（《五灯会元》卷六。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-67e74460-e7c4-4b9b-b7eb-81f72b898b62","tags":[]},{"id":"poem-b9bc548e7f70208af0b4b9b1","title":"画堂春·外潮莲子长参差","author":"张先","dynasty":"宋","verses":["外潮莲子长参差。","霁山青处鸥飞。","水天溶漾画桡迟。","人影鉴中移。","桃叶浅声双唱，杏红深色轻衣。","小荷障面避斜晖。","分得翠阴归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-397","tags":[]},{"id":"poem-b9bde1c26699ace215482ca3","title":"次北固山下","author":"王湾","dynasty":"唐","verses":["客路青山外，行舟绿水前。","潮平两岸阔，风正一帆悬。","海日生残夜，江春入旧年。","乡书何处达，归雁洛阳边。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-5bb5c590-5de8-4bfb-aee6-30bc4bcdf99a","tags":["唐诗三百首","七年级上册(课内)","地点","五言律诗","初中古诗","哲理","思乡"]},{"id":"poem-b9c00279cb1985df98254251","title":"九章·惜诵","author":"屈原","dynasty":"先秦","verses":["惜诵以致愍兮，发愤以抒情。","所作忠而言之兮，指苍天以为正。","令五帝使折中兮，戒六神与向服。","俾山川以备御兮，命咎繇使听直。","竭忠诚而事君兮，反离群而赘肬。","忘儇媚以背众兮，待明君其知之。","言与行其可迹兮，情与貌其不变。","故相臣莫若君兮，所以证之不远。","吾谊先君而后身兮，羌众人之所仇也。","专惟君而无他兮，又众兆之所雠也。","壹心而不豫兮，羌无可保也。","疾亲君而无他兮，有招祸之道也。","思君其莫我忠兮，忽忘身之贱贫。","事君而不贰兮，迷不知宠之门。","患何罪以遇罚兮，亦非余之所志也。","行不群以巅越兮，又众兆之所咍也。","纷逢尤以离谤兮，謇不可释也。","情沉抑而不达兮，又蔽而莫之白也。","心郁邑余侘傺兮，又莫察余之中情。","固烦言不可结而诒兮，愿陈志而无路。","退静默而莫余知兮，进号呼又莫吾闻。","申侘傺之烦惑兮，中闷瞀之忳忳。","昔余梦登天兮，魂中道而无杭。","吾使厉神占之兮，曰有志极而无旁。","终危独以离异兮，曰君可思而不可恃。","故众口其铄金兮，初若是而逢殆。","惩于羹者而吹齑兮，何不变此志也？","欲释阶而登天兮，犹有曩之态也。","众骇遽以离心兮，又何以为此伴也？","同极而异路兮，又何以为此援也？","晋申生之孝子兮，父信谗而不好。","行婞直而不豫兮，鲧功用而不就。","吾闻作忠以造怨兮，忽谓之过言。","九折臂而成医兮，吾至今而知其信然。","矰弋机而在上兮，罻罗张而在下。","设张辟以娱君兮，愿侧身而无所。","欲儃徊以干傺兮，恐重患而离尤。","欲高飞而远集兮，君罔谓汝何之？","欲横奔而失路兮，盖志坚而不忍。","背膺牉以交痛兮，心郁结而纡轸。","捣木兰以矫蕙兮，糳申椒以为粮。","播江离与滋菊兮，愿春日以为糗芳。","恐情质之不信兮，故重著以自明。","矫兹媚以私处兮，愿曾思而远身。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-13","tags":[]},{"id":"poem-b9c2010dbc60f00cfd887f74","title":"月上海棠·孟婆且与我、做些方便","author":"赵佶","dynasty":"宋","verses":["孟婆且与我、做些方便。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-533","tags":[]},{"id":"poem-b9c5c38856ca3940df2d7d0b","title":"溪上遇雨二首 二","author":"崔道融","dynasty":"唐","verses":["坐看黑云衔猛雨，喷洒前山此独晴。","忽惊云雨在头上，却是山前晚照明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-df968053-5d06-4c13-ac3f-5b8cf26e433f","tags":[]},{"id":"poem-b9d0351e390d45697be3370c","title":"送黄梅江明府","author":"徐铉","dynasty":"宋","verses":["封疆多难正经纶，台阁如何不用君。","江上又劳为小邑，箧中徒自有雄文。","书生胆气人谁信，远俗歌谣主不闻。","一首新诗无限意，再三吟咏向秋云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6020c922-18ab-4981-aeec-08a63a6e98be","tags":[]},{"id":"poem-b9d92f1a9affabe0ae507d69","title":"春社","author":"王同祖","dynasty":"宋","verses":["廉纤雾雨四山昏，寂寂茅簷半掩门。","客里不知今日社，偶过野庙见分膰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1b2050cc-c15d-4c89-84b4-b2b193436da2","tags":[]},{"id":"poem-b9e656723952fd59b851f107","title":"小圃即事四首  其二","author":"释居简","dynasty":"宋","verses":["恰则夭夭看小桃，靓粧撚指九分消。","丁宁更耐明朝雨，款曲随风送落潮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-674587ed-c991-4d87-90d0-54287189ae42","tags":[]},{"id":"poem-b9f17776f385b43eb40275ff","title":"循梅道中遣人如江南走笔寄诸季十首  其三","author":"李纲","dynasty":"宋","verses":["人传吴会破，虏向福山归。","松梓定安稳，池台今是非。","伤心怀故老，流泪落征衣。","目断沧波上，龙舟翠盖飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5cf5bdd2-04c0-4ea0-9fcf-7e3ead42891a","tags":[]},{"id":"poem-ba00800acf2c01c43d186408","title":"题安乐山","author":"先汪","dynasty":"唐","verses":["碧峰横倚白云端，隋氏真人化迹残。","翠栢不凋龙骨瘦，石泉犹在镜光寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-16488c94-8f7e-4277-bdc9-fe83bce4a670","tags":[]},{"id":"poem-ba01be855043e8f24eae1f89","title":"菩萨蛮·一枝绛蜡香梅软","author":"李元卓","dynasty":"宋","verses":["一枝绛蜡香梅软。","宜春小胜玲珑剪。","拂晓上瑶钗。","春从鬓底来。","菱花频自照。","粉面惊春早。","淡拂晓山眉。","为谁今日宜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-626","tags":[]},{"id":"poem-ba0c7af87db68ffc9064b571","title":"牡丹  其二","author":"李山甫","dynasty":"宋","verses":["嫚黄妖紫间轻红，谷雨初晴早景中。","静女不言还爱日，彩云无定只随风。","炉烟坐觉沈檀薄，妆面行看晓黛空。","此别又须经岁月，酒阑把烛绕芳丛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b32cb9d6-9a32-4412-9431-49655c2361f7","tags":[]},{"id":"poem-ba136df370b400b2231aa555","title":"尾","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["月再圆，花重发，那其间欢生喜洽，重整华筵泛紫霞。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8256","tags":[]},{"id":"poem-ba21d0930a06bab3dd7bfdbb","title":"如梦令·小院春风不老","author":"史浩","dynasty":"宋","verses":["小院春风不老。","鹊碧霓裳缥缈。","雪脸间朱颜，各自一般轻妙。","忒掉。","忒掉。","真个一双两好。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-104","tags":[]},{"id":"poem-ba24a4d0eb3147f6be4b106f","title":"北风","author":"佚名","dynasty":"先秦","verses":["北风其凉，雨雪其雱。惠而好我，携手同行。其虚其邪？既亟只且！","北风其喈，雨雪其霏。惠而好我，携手同归。其虚其邪？既亟只且！","莫赤匪狐，莫黑匪乌。惠而好我，携手同车。其虚其邪？既亟只且！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-40","tags":[]},{"id":"poem-ba2aa666d17aec4352167091","title":"写真","author":"澹交","dynasty":"唐","verses":["图形期自见，自见却伤神。","已是梦中梦，更逢身外身。","水花凝幻质，墨彩染空尘。","堪笑予兼尔，俱为未了人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4c16c60c-2206-4dcc-af22-a82767c13be2","tags":[]},{"id":"poem-ba49ebaa6aaff73279199b93","title":"嘉祐寺留别丕上人","author":"皮公弼","dynasty":"宋","verses":["两年无惠及编氓，蜀道天难六月行。","深羡高僧捐世累，竹风湖处听泉声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5de36452-1fcd-4250-8b09-1fd0b5d6f40d","tags":[]},{"id":"poem-ba4d069bc52ca994c7bffddc","title":"寄宇文邛州","author":"张栻","dynasty":"宋","verses":["寄语临邛守，相望万里情。","有来诗句好，足验教条清。","好古从时讪，为邦已政成。","无寻子虚赋，忠厚诏诸生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c6c8c6d3-ff44-4d97-8d48-810a81179976","tags":[]},{"id":"poem-ba536fbfe2ed5a4a1be71ee3","title":"燕歌行","author":"屈同仙","dynasty":"唐","verses":["君不见渔阳八月塞草腓，征人相对并思归。","云和朔气连天黑，蓬杂惊沙散野飞。","是时天地阴埃遍，瀚海龙城皆习战。","两军鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄无厌不复和。","汉兵候月秋防塞，胡骑乘冰夜渡河。","河塞东西万余里，地与京华不相似。","燕支山下少春晖，黄沙碛里无流水。","金戈玉剑十年征，红粉青楼多怨情。","厌向殊乡久离别，秋来愁听捣衣声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7715e2f7-4e7e-4794-942e-bfbad57f953d","tags":[]},{"id":"poem-ba7b748ae7b9c4af7a81a333","title":"赠兄","author":"何兆","dynasty":"唐","verses":["洛阳纸价因兄贵，蜀地红牋为弟贫。","南北东西九千里，除兄与弟更无人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d22f1a49-5ef6-4df6-b365-f9ba2fe2442c","tags":[]},{"id":"poem-ba7d69c14fa104d557f91bee","title":"降诞日内庭献寿应制","author":"广宣","dynasty":"唐","verses":["庆寿千龄远，敷仁万国通。","登霄欣有路，捧日媿无功。","仙驾三山上，龙生二月中。","修斋长乐殿，讲道大明宫。","此地人难到，诸天事不同。","法筵花散后，空界满香风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-21cc13eb-a312-48f6-b334-e28b334b45bf","tags":[]},{"id":"poem-ba89d647e0e48c34a6f7cf16","title":"菊花新","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["深感当今圣主，恩赐金紫双鱼。","公心正直遍采访，治国安民，但愿得国泰岁时丰富。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-334","tags":[]},{"id":"poem-ba8d9d74179f8d6c30cd25d9","title":"郊庙歌辞 仪坤庙乐章 永和","author":"徐彦伯","dynasty":"唐","verses":["猗若清庙，肃肃荧荧。","国荐严祀，坤兴淑灵。","有几在室，有乐在庭。","临兹孝享，百禄惟宁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1c5a317d-fe60-4e67-a0b5-a9ed42e5aa6a","tags":[]},{"id":"poem-ba8f67dff1a5adbe8a12a3e1","title":"句  其三","author":"王十朋","dynasty":"宋","verses":["太虚怀抱物华秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-392a81a3-9932-41f3-934b-d75d7c6e9862","tags":[]},{"id":"poem-ba95ba9565fba35a8ea2fa3b","title":"南乡子·潮落去帆收","author":"陈师道","dynasty":"宋","verses":["潮落去帆收。","沙涨江回旋作洲。","侧帽独行斜照里，飕飕。","卷地风前更掉头。","语妙后难酬。","回雁峰南未得秋。","唤取佳人听旧曲，休休。","瘴雨无花孰与愁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-302","tags":[]},{"id":"poem-ba97a4605b1e4b3d1a6a23b1","title":"题壁","author":"钱氏","dynasty":"宋","verses":["落日西风照楚关，断魂残魄吊衰颜。","自从鸿鹄分飞后，无复鸳鸯并枕间。","腕玉瘦宽金缕袖，鬓蝉慵掠翠云鬟。","秋天冬暮风雪寒，对镜懒把金蝉簇。","梦魂夜夜到君边，觉来寂寞鸳衾独。","此时行坐闲纱窗，忍泪含情眉黛蹙。","古人惜别日三秋，不知君去几多宿。","山高水阔三千里，名利使人复尔耳。","昔年曾拨伯牙弦，未遇知音莫怨天。","去年又奏相如赋，汉殿依前还不遇。","时人不知双字讹，平川倏忽风波起。","当时南宫报罢音，教妾沉吟杵中心。","为君滴下红粉泪，红罗帐里湿鸳衾。","愤愤调琴蝉鹊噪，默默吟诗怨桂林。","千调万拨不成曲，争奈胸中气相掬。","千思万想不成诗，心如死灰谁得知。","料得君心当此际，事国繁华闲田地。","朝朝暮暮望君归，日在东隅月在西。","碧落翩翩飞雁过，青山切切子规啼。","望尽一月复一月，不见音容寸肠结。","又闻君自河东来，夜夜不教红烛灭。","鸡鸣犬唳侧耳听，寂寂不闻车马音。","自此知君无定止，一片情怀冷如水。","既无黄耳寄家书，也合随时寄雁鱼。","日月逡巡又一年，何事归期竟杳然。","鲛绡裛遍相思泪，眉黛无心画远山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-49fd63b6-6dfa-40d2-bae1-1757e00ab49b","tags":[]},{"id":"poem-ba99a1b46973c041be0762c5","title":"短歌行 其二","author":"曹操","dynasty":"汉","verses":["周西伯昌，怀此圣德。","三分天下，而有其二。","修奉贡献，臣节不隆。","崇侯谗之，是以拘系。","后见赦原，赐之斧钺，得使征伐。","为仲尼所称，达及德行，犹奉事殷，论叙其美。","齐桓之功，为霸之首。","九合诸侯，一匡天下。","一匡天下，不以兵车。","正而不谲，其德传称。","孔子所叹，并称夷吾，民受其恩。","赐与庙胙，命无下拜。","小白不敢尔，天威在颜咫尺。","晋文亦霸，躬奉天王。","受赐圭瓒，秬鬯彤弓，卢弓矢千，虎贲三百人。","威服诸侯，师之所尊。","八方闻之，名亚齐桓。","河阳之会，诈称周王，是其名纷葩。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-2","tags":[]},{"id":"poem-ba9b1a104e47e5737e48d6b7","title":"送造微上人游五台及礼本师","author":"栖白","dynasty":"唐","verses":["寒空金锡响，欲过渭阳津。","极目多来鴈，孤城少故人。","与师虽别久，于法本相亲。","又对清凉月，中宵语宿因。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b0d76d62-cd8f-419b-863d-bdbadf291422","tags":[]},{"id":"poem-baa58d82e90086d5cce4627c","title":"和主司王起","author":"裴翻","dynasty":"唐","verses":["常将公道选群生，犹被春闱屈重名。","文柄久持殊岁纪，恩门三启动寰瀛。","云霄幸接鸳鸾盛，变化欣同草木荣。","乍得阳和如细柳，参差长近亚夫营。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-78b7af99-f1d7-4db1-b2cf-d2f419c6fd30","tags":[]},{"id":"poem-baa8d4cc80cd8e95ff2431f8","title":"晓鹤","author":"孟郊","dynasty":"唐","verses":["晓鹤弹古舌，婆罗门叫音。","应吹天上律，不使尘中寻。","虚空梦皆断，歆唏安能禁。","如开孤月口，似说明星心。","既非人间韵，枉作人间禽。","不如相将去，碧落窠巢深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d367dabb-1d6d-4392-aa3a-a1d945cad8de","tags":[]},{"id":"poem-baacacbdd32f16165ec9a612","title":"杂曲歌辞 行路难三首 三","author":"李白","dynasty":"唐","verses":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机才多岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道？君不见吴中张翰称达士，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b4f9c5b3-0108-4127-bf3e-73fd207176f3","tags":["唐诗三百首","人生","乐府","态度"]},{"id":"poem-baad4c6e635dba0cc38016f7","title":"登高","author":"杜甫","dynasty":"唐","verses":["风急天高猨啸哀，渚清沙白鸟飞回。","无边落木萧萧下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艰难苦恨繁霜鬓，潦倒新停浊酒桮。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a4d718ee-c020-42b4-97df-499cd0076f7b","tags":["唐诗三百首","长江","七言律诗","写景","忧国忧民","秋天","登高","抒情"]},{"id":"poem-bab084e8229974492c47f557","title":"早春","author":"白玉蟾","dynasty":"宋","verses":["南枝才放两三花，雪里吟香弄粉些。","淡淡著烟浓著月，深深笼水浅笼沙。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-早春","tags":[]},{"id":"poem-bac6f74eb22ee85afff924c4","title":"游仙窟诗 别文成","author":"崔十娘","dynasty":"唐","verses":["别时终是别，春心不值春。","羞见孤鸾影，悲看一骑尘。","翠柳开眉色，红桃乱脸新。","此时君不在，娇莺弄杀人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0f76e61f-912a-4308-b2dc-d419a3f51b38","tags":[]},{"id":"poem-bacb41e484e6158aee5465e3","title":"王升之绝句以诗成有共赋酒熟无孤斟为韵因次其韵  其四","author":"刘跂","dynasty":"宋","verses":["欲逃苏晋禅，苦乏阳城俸。","邻家称子贫，杯酌与君共。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-86192a19-2b0f-496e-9c1b-e10de213abe6","tags":[]},{"id":"poem-bad41094a4d4d94fbdb0bccb","title":"端康之间地名越城五山秀峙有蜿蜒飞跃之状山有五龙庙当秦时神媪临江五龙从之游没葬山上庙祀至今灵响甚著乡人以风雨候龙之归因作送迎辞五绝句以遗之  其四","author":"李纲","dynasty":"宋","verses":["贝阙珠宫不可寻，时因风雨听清吟。","叶公好画真龙出，却恨今无好画心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8cd1566f-d8d1-4da4-a9c2-e99ffed94d87","tags":[]},{"id":"poem-bad56a5c8eb75c331af21341","title":"寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物","author":"李绅","dynasty":"唐","verses":["垂阴敢慕甘棠叶，附干将呈瑞木符。","十步兰茶同秀彩，万年枝叶表皇图。","芟夷不及知无患，雨露曾沾自不枯。","好住孤根托桃李，莫令从此混樵苏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-55f2083d-f3ec-4f8d-8372-dabfc656e9cf","tags":[]},{"id":"poem-bad6b836f790b7b35f73f9fc","title":"和左衞武仓曹衞中对雨创韵赠右衞李骑曹","author":"孙逖","dynasty":"唐","verses":["林父同官意，宣尼久敬交。","文场刊玉篆，武事掌金铙。","道合宜连茹，时清岂系匏。","克勤居簿领，多暇屏讙𫍢。","美酒怀公䜩，玄谈俟客嘲。","薄云生北阙，飞雨自西郊。","院暑便清旷，庭芜觉渐苞。","高门关讵闭，逸韵柱难胶。","枳棘鸾无叹，椅梧凤必巢。","忽闻征竝作，观海媿堂坳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c4b4899e-7941-49e6-8f62-4f84e97031f6","tags":[]},{"id":"poem-bad74e7cc2ec8693883dd9ec","title":"虞美人·梅花自是于春懒","author":"吕本中","dynasty":"宋","verses":["梅花自是于春懒。","不是春来晚。","看伊开在众花前。","便道与春无分、结因缘。","风前月下频相就。","笑我如伊瘦。","几回冲雨过疏篱。","已见一番青子、缀残枝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-733","tags":[]},{"id":"poem-baef0419f106d3d90da1709f","title":"萧宅二三子赠答诗二十首 客请马兰","author":"卢仝","dynasty":"唐","verses":["嵩山未必怜兰兰，兰兰已受郎君恩。","不须刷帚跳踪走，只拟兰浪出其门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e610c414-386a-433d-98d3-f8ac508574ec","tags":[]},{"id":"poem-baf0db7a82231304ea531621","title":"玉井莲后","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["忍饿担饥，未知何日是了？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5068","tags":[]},{"id":"poem-baf4ce24550dcce6425633eb","title":"峡哀 八","author":"孟郊","dynasty":"唐","verses":["峡景滑易堕，峡花怪非春。","红光根潜涎，碧雨飞沃津。","巴谷蛟螭心，巴乡魍魉亲。","噉生不问贤，至死独养身。","腥语信者谁，拗歌欢非真。","仄田无异稼，毒水多狞鳞。","异类不可友，峡哀哀难伸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e8d89175-a6e3-493b-84f7-86eb548a0ce6","tags":[]},{"id":"poem-baf674be784b02843bfa5219","title":"题曹娥庙","author":"赵嘏","dynasty":"唐","verses":["青娥埋没此江滨，江树飕飗惨暮云。","文字在碑碑已堕，波涛辜负色丝文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-dfe5d78a-8fc0-46ab-916c-6afacddc4ff0","tags":[]},{"id":"poem-baf6eeca098b35dade363a34","title":"故福国夫人挽歌词  其二","author":"綦崇礼","dynasty":"宋","verses":["蜀都旌节继辉光，象服重来意独伤。","许国毋辞驱远驭，怀人忍复舍中堂。","新阡岂料今同穴，异县端如在故乡。","错顾飞云何处是，西山松槚已成行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c0078ade-9a63-4783-b8b3-b755845e07fb","tags":[]},{"id":"poem-bb000fcd22f136882051e62d","title":"孤鴈 二","author":"崔涂","dynasty":"唐","verses":["几行归去尽，片影独何之。","暮雨相呼失，寒塘独下迟。","渚云低暗度，关月冷遥随。","未必逢矰缴，孤飞自可疑。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c836e52f-2346-4a3e-84bb-97514b17faf6","tags":["唐诗三百首","孤独","羁旅","五言律诗","写鸟","组诗","鸟"]},{"id":"poem-bb0dda0a6b7bb03f29c4b580","title":"和留守相公九月八日与潞公宴赵令园有怀去年与景仁秉国游赏","author":"司马光","dynasty":"宋","verses":["今歳台星聚洛中，甘棠前后雨阴浓。","英辞唱和诗千首，高宴游陪禄万锺。","木末霜繁花未落，云间字小鴈相从。","西湖在望亲朋远，节物那堪处处逢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d0ca4b5a-2cc6-49df-ae0f-0cd3509cee1f","tags":["西湖"]},{"id":"poem-bb149aaf325bc649b53e46bc","title":"送裴参军还下邳旧居","author":"皎然","dynasty":"唐","verses":["北望烟铺骠骑营，虏烽无火楚天晴。","此时千里西归客，泗上春风得及耕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ecd7e63d-8c05-4af2-9018-05064797df28","tags":[]},{"id":"poem-bb18ccdef330166411934994","title":"化城寺","author":"陈岩","dynasty":"宋","verses":["匝径茸茸菜甲青，透池艳艳藕花明。","四方衲子寻幽践，多少空山振锡声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b206bdbf-d8e5-482b-a690-832d7b273c18","tags":[]},{"id":"poem-bb1ad20e1b5a6d687f0a5068","title":"书殿赐宴应制","author":"徐安贞","dynasty":"唐","verses":["校文常近日，赐宴忽升天。","酒正传桮至，饔人捧案前。","玉阶鸣溜水，清阁引归烟。","共惜芸香暮，春风几万年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-06a2961a-ef57-431e-ba01-70fb91a5feac","tags":[]},{"id":"poem-bb1b96f36387859d8e37a25f","title":"南乡子·倾绿蚁","author":"李珣","dynasty":"五代","verses":["倾绿蚁，泛红螺，闲邀女伴簇笙歌。","避暑信船轻浪里，闲游戏，夹岸荔枝红蘸水。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-29","tags":[]},{"id":"poem-bb258f0baa256a82f90a9022","title":"观公孙大娘弟子舞劒器行","author":"杜甫","dynasty":"唐","verses":["昔有佳人公孙氏，一舞劒气动四方。","观者如山色沮丧，天地为之久低昂。","㸌如羿射九日落，矫如群帝骖龙翔。","来如雷霆收震怒，罢如江海凝清光。","绛唇珠袖两寂莫，况有弟子传芬芳。","临颍美人在白帝，妙舞此曲神扬扬。","与余问答既有以，感时抚事增惋伤。","先帝侍女八千人，公孙劒器初第一。","五十年间似反掌，风尘倾动昏王室。","棃园子弟散如烟，女乐余姿映寒日。","金粟堆南木已拱，瞿唐石城草萧瑟。","玳筵急管曲复终，乐极哀来月东出。","老夫不知其所往，足茧荒山转愁疾。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-61304178-6b16-4f98-87b2-4ad6bc98da98","tags":["唐诗三百首"]},{"id":"poem-bb25ceeba1b328023cdda919","title":"行雪","author":"赵文","dynasty":"宋","verses":["夜寒枕席跳霰珠，夜深我睡霰亦无。","未晨仆起索炊火，怪见满地琼瑶铺。","我行至此不得止，但倚红酒为先驱。","路逢十店九闭户，苦寒正自无薪刍。","终然著地即化去，造物何用劳工夫。","前山欲融未融处，玉龙浮动青珊瑚。","藤梢竹刺时点缀，寒食野花栖路隅。","小车行雪真有益，平生看画无此笔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-844b636d-5ba6-4e31-9734-b8d90cc3fe65","tags":[]},{"id":"poem-bb265b16e5213bfa3e1f51ac","title":"升平词十首 七","author":"薛能","dynasty":"唐","verses":["品物尽昭苏，神功复帝谟。","他时应有寿，当代且无虞。","赐历通遐俗，移关入半胡。","鹪鹩一何幸，于此寄微躯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c72a9af5-ed08-4627-bf20-9ee339648f41","tags":[]},{"id":"poem-bb26e450c6854508455e0165","title":"喜广仲伯逢来会","author":"张栻","dynasty":"宋","verses":["二阮向来俱莫逆，支筇为我到山巅。","浊醪共饮聊复尔，胜集于今亦偶然。","人立千峰秋色里，月生沧海暮云边。","高谈此地曾知几，一笑归来对榻眠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1bda096c-c450-467c-badb-91235f4de3a4","tags":[]},{"id":"poem-bb331a692db4588b1e8296e0","title":"题友人草堂","author":"张乔","dynasty":"唐","verses":["空山卜隐初，生计亦无余。","三亩水边竹，一床琴畔书。","深林收晚果，绝顶拾秋蔬。","坚话长如此，何年献子虚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2bcc1839-e35b-4608-89cb-316bc863911f","tags":[]},{"id":"poem-bb363ba89f0fe30998a38357","title":"德升尚书出示岁除用韦苏州韵前后二篇及两郎属和粲然盈轴赏叹之余有感于中亦輙次韵书山居一时事  其一","author":"綦崇礼","dynasty":"宋","verses":["寒宵送徂岁，青灯照华髪。","天时自代谢，人事更治忽。","圣朝今中兴，正朔几书月。","未作故乡归，又见新花发。","稚女巧娱予，剪彩粧风物。","一釂婪尾觞，頺然百忧歇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-fd47e7cb-5d5e-4b3a-9883-c6dcf439fad7","tags":[]},{"id":"poem-bb372d16bf138a97cd403edc","title":"梦江南·昏鸦尽","author":"纳兰性德","dynasty":"清","verses":["昏鸦尽，小立恨因谁。","急雪乍翻香阁絮，轻风吹到胆瓶梅，心字已成灰。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-21","tags":[]},{"id":"poem-bb379622be93105067e02b73","title":"安上座所作墨梅","author":"释士珪","dynasty":"宋","verses":["道人色心浄，了见造物根。","笔端开此花，胸中有丘园。","清香凝暗夜，疏枝卧黄昏。","撞钟西湖寺，见月罗浮村。","老眼隔烟雾，一笑作篱藩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-88bd9e91-ce3f-43b0-abfa-e66d18682cee","tags":["西湖"]},{"id":"poem-bb40128049b641ad3b14fcb0","title":"寄曹松","author":"裴说","dynasty":"唐","verses":["莫怪苦吟迟，诗成鬓亦丝。","鬓丝犹可染，诗病却难医。","山暝云横处，星沈月侧时。","冥搜不可得，一句至公知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5779950b-aa62-4bcb-a185-429204d80b7c","tags":[]},{"id":"poem-bb4b55780eb0c265d35ca722","title":"苏大侍御访江浦赋八韵记异","author":"杜甫","dynasty":"唐","verses":["庞公不浪出，苏氏今有之。","再闻诵新作，突过黄初诗。","乾坤几反复，扬马宣同时。","今晨清镜中，胜食斋房芝。","余发喜却变，白间生黑丝。","昨夜舟火灭，湘娥帘外悲。","百灵未敢散，风破寒江迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e263d29c-c7b0-4cd9-a1ef-d7426a8846c8","tags":[]},{"id":"poem-bb5370862d732a643d11463e","title":"郊庙歌辞 祭方丘乐章 金奏","author":"不详","dynasty":"唐","verses":["坤元至德，品物资生。","神凝博厚，道协高明。","列镇五岳，环流四瀛。","于何不载，万宝斯成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7c643aeb-d85f-4619-87e5-ba68c9880228","tags":[]},{"id":"poem-bb56b4d309086bc3cca5dc0b","title":"帝台春·芳草碧色","author":"李甲","dynasty":"宋","verses":["芳草碧色，萋萋遍南陌。","暖絮乱红，也知人、春愁无力。","忆得盈盈拾翠侣，共携赏、凤城寒食。","到今来，海角逢春，天涯为客。","愁旋释。","还似织。","泪暗拭。","又偷滴。","谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。","拼则而已今拼了，忘则怎生便忘得。","又还问鳞鸿，试重寻消息。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-71","tags":["宋词三百首"]},{"id":"poem-bb6624366a714256014bda63","title":"写情","author":"李益","dynasty":"唐","verses":["水纹珍簟思悠悠，千里佳期一夕休。","从此无心爱良夜，任他明月下西楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1cb66aa8-e665-40b5-af59-253d8592f137","tags":["失恋","爱情"]},{"id":"poem-bb6d316f74d446233d3dde22","title":"雒中寒夜姚侍御宅怀贾岛","author":"马戴","dynasty":"唐","verses":["夜木动寒色，雒阳城阙深。","如何异乡思，更抱故人心。","微月关山远，闲堦霜霰侵。","谁知石门路，待与子同寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f4562dfc-b136-4ff9-bb53-0488eaab0424","tags":[]},{"id":"poem-bb71159f846f59b7777cb5fd","title":"粉蝶儿·雪遍梅花","author":"毛滂","dynasty":"宋","verses":["雪遍梅花，素光都共奇绝。","到窗前、认君时节。","下重帏，香篆冷，兰膏明灭。","梦悠扬，空绕断云残月。","沈郎带宽，同心放开重结。","褪罗衣、楚腰一捻。","正春风，新著摸，花花叶叶。","粉蝶儿，这回共花同活。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-888","tags":[]},{"id":"poem-bb7e2119a70fed985648e9cc","title":"入邑阻风  其一","author":"释居简","dynasty":"宋","verses":["鬭风鹢退不忺飞，还似当年过宋时。","又似雪舟人兴尽，归时却是顺风吹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1aadc8b0-49df-4951-a5e4-4cc358618587","tags":[]},{"id":"poem-bb8df3deeb6b80920543a10f","title":"西江月·席上酒杯难减","author":"洪适","dynasty":"宋","verses":["席上酒杯难减，鼎中药味频加。","老人争得脸如霞。","镜里衰容人怕。","檐溜尽成冰柱，前村变却梅花。","琼瑶破碎为行车。","冻雀盈枝堪画。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-771","tags":[]},{"id":"poem-bb97fbc8d110cd9174039913","title":"临江仙·夜饮东坡醒复醉","author":"苏轼","dynasty":"宋","verses":["夜饮东坡醒复醉，归来仿佛三更。","家童鼻息已雷鸣。","敲门都不应，倚杖听江声。","长恨此身非我有，何时忘却营营。","夜阑风静縠纹平。","小舟从此逝，江海寄馀生。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-39","tags":["宋词三百首"]},{"id":"poem-bb9cfd9f21bdcda5a4001bc0","title":"赞镜灯颂","author":"惟劲","dynasty":"唐","verses":["伟哉真智士，能开方便津。","一灯明一体，十镜现十身。","身身相暵涉，灯灯作{牙丿=丶}因。","层层身土广，重重理事渕。","俨覩微尘佛，等逢毗目仙。","海印从兹显，帝纲义由诠。","一尘说法界，一切尘亦然。","五蕴十八界，寂用体俱全。","圆光含镜像，一异不可宣。","达斯无㝵境，无那法报圆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-609e47f6-22b0-4261-8955-12da2cb20e07","tags":[]},{"id":"poem-bba35855b0f9a6bb63e91d84","title":"山居诗  其四四","author":"释延寿","dynasty":"宋","verses":["万境闲来情澹澹，群嚣息后思微微。","当时白业无门入，今日玄关有路归。","熟果不摇翻自落，生禽谁唤却惊飞。","到头何用空忙得，任运应须待对机。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-35674b93-129e-4cf4-9ca3-6008186c142e","tags":[]},{"id":"poem-bba9f09bdf3cbad0de35320b","title":"淮上逢故人","author":"贯休","dynasty":"唐","verses":["故园离乱后，十载始逢君。","长恨南熏奏，寻常只自闻。","荒窗秋见岳，赤地夜生云。","莫叹谋身晚，中兴正用文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3ec8c54b-2eda-48f6-b177-99b116d27b07","tags":[]},{"id":"poem-bbad82ecaac0e215173a63e1","title":"鉴远楼","author":"米芾","dynasty":"宋","verses":["赏心亭上群山雪，三夕丹渊借月华。","吟尽江南清绝趣，亟行归觐紫皇家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9d15c724-9b9d-44a0-ba8f-0583d1c5941d","tags":[]},{"id":"poem-bbae9f83d3d893ac637e940f","title":"冬日洛城北谒玄元皇帝庙","author":"杜甫","dynasty":"唐","verses":["配极玄都閟，凭虚禁御长。","守祧严具礼，掌节镇非常。","碧瓦初寒外，金茎一气旁。","山河扶绣户，日月近雕梁。","仙李盘根大，猗兰奕叶光。","世家遗旧史，道德付今王。","画手看前辈，吴生远擅场。","森罗移地轴，妙绝动宫墙。","五圣联龙衮，千官列雁行。","冕旒俱秀发，旌斾尽飞扬。","翠柏深留景，红棃迥得霜。","风筝吹玉柱，露井冻银床。","身退卑周室，经传拱汉皇。","谷神如不死，养拙更何乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-883fcd05-a7b4-40f8-8cbe-5d93d4fad76c","tags":[]},{"id":"poem-bbc3b502f67b81d0379b1ea8","title":"月","author":"张南史","dynasty":"唐","verses":["月，月。","暂盈，还缺。","上虚空，生溟渤。","散彩无际，移轮不歇。","桂殿入西秦，菱歌映南越。","正看云雾秋卷，莫待关山晓没。","天涯地角不可寻，清光永夜何超忽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-45e3e037-699c-41df-a14f-9c2835334fcc","tags":[]},{"id":"poem-bbe00935b0f0ee226b7eb791","title":"句 二","author":"延寿","dynasty":"唐","verses":["绕绣屏飞花外蝶，隔金笼语柳中莺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-18d51aee-f00f-4dab-b773-61f63eb9e470","tags":[]},{"id":"poem-bbe0f5b9203dc30b70f664e8","title":"北门","author":"佚名","dynasty":"先秦","verses":["出自北门，忧心殷殷。终窭且贫，莫知我艰。已焉哉！天实为之，谓之何哉！","王事适我，政事一埤益我。我入自外，室人交遍谪我。已焉哉！天实为之，谓之何哉！","王事敦我，政事一埤遗我。我入自外，室人交遍摧我。已焉哉！天实为之，谓之何哉！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-39","tags":[]},{"id":"poem-bbe6b089718bb118a5759aef","title":"赠元秘书","author":"崔峒","dynasty":"唐","verses":["旧书稍稍出风尘，孤客逢秋感此身。","秦地谬为门下客，淮阴徒笑市中人。","也闻阮籍寻常醉，见说陈平不久贫。","幸有故人茅屋在，更将心事问情亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dabb5b5f-fe33-4632-93ce-e32f638296b1","tags":[]},{"id":"poem-bbeab124748516338f4a81e2","title":"谒衡岳庙遂宿岳寺题门楼","author":"韩愈","dynasty":"唐","verses":["五岳祭秩皆三公，四方环镇嵩当中。","火维地荒足妖怪，天假神柄专其雄。","喷云泄雾藏半腹，虽有绝顶谁能穷。","我来正逢秋雨节，阴气晦昧无清风。","潜心默祷若有应，岂非正直能感通。","须臾静扫众峰出，仰见突兀撑青空。","紫盖连延接天柱，石廪腾掷堆祝融。","森然魄动下马拜，松柏一迳趋灵宫。","粉墙丹柱动光彩，鬼物图画填青红。","升阶伛偻荐脯酒，欲以菲薄明其衷。","庙令老人识神意，睢盱侦伺能鞠躬。","手持桮珓导我掷，云此最吉余难同。","窜逐蛮荒幸不死，衣食才足甘长终。","侯王将相望久绝，神纵欲福难为功。","夜投佛寺上高阁，星月掩暎云朣胧。","猿鸣钟动不知曙，杲杲寒日生于东。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-14ae27a0-2641-41e6-8c0a-60a9185f8b6d","tags":["唐诗三百首","登高","七言古诗","寺庙"]},{"id":"poem-bbf1ce1b330ee45c6d502728","title":"漫成  其二","author":"綦崇礼","dynasty":"宋","verses":["书迷今古懒不读，樽列圣贤时一中。","顾我本无当世志，爱君真有古人风。","赐环忽恐归期促，放盏常嗟乐事空。","山鹿野麋便茂草，鳯凰终合止梧桐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-1b2a64db-ce64-4581-9430-4ab65616f32b","tags":[]},{"id":"poem-bbf30208cfb7a7544ec8563a","title":"尾","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["昏昏默默归何处？哽哽咽咽思念你。","直上嫦娥宫殿里。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8277","tags":[]},{"id":"poem-bc006125073cf635465acd26","title":"狼跋","author":"佚名","dynasty":"先秦","verses":["狼跋其胡，载疐其尾。公孙硕肤，赤舄几几。","狼疐其尾，载跋其胡。公孙硕肤，德音不瑕？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-159","tags":[]},{"id":"poem-bc0889502759acacb5b770bd","title":"过太乙观贾生房","author":"王维","dynasty":"唐","verses":["昔余栖遯日，之子烟霞邻。","共携松叶酒，俱𥮾竹皮巾。","攀林遍岩洞，采药无冬春。","谬以道门子，征为骖御臣。","常恐丹液就，先我紫阳宾。","夭促万涂尽，哀伤百虑新。","迹峻不容俗，才多反累真。","泣对双泉水，还山无主人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8d05b6e8-b232-40e7-a66d-41d8980f00d5","tags":[]},{"id":"poem-bc107dc1f927b9da15506e92","title":"古意四首  其一","author":"李纲","dynasty":"宋","verses":["鸾凤招不来，鸱鸢麾不去。","君看酒肉败，坐使醯鸡聚。","小人为身谋，无复及远虑。","国敝身亦危，何殊木中蠧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a2c87561-3598-44b3-a967-ee2ef9f38106","tags":[]},{"id":"poem-bc1517899f53905e1706d90f","title":"题东林二首 一","author":"匡白","dynasty":"唐","verses":["东林佳景一何长，兰蕙生多地亦香，堪叹世人来不得，便随云树老何妨。","倚天苍翠晴当户，落[石]潺湲夜遶廊。","到此秪除重结社，自余闲事莫思量。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-554fbeb3-2110-4ede-9da2-7ed4890ed41d","tags":[]},{"id":"poem-bc15273bd9b26915d9d8d782","title":"清平乐·凄凄切切","author":"纳兰性德","dynasty":"清","verses":["凄凄切切，惨澹黄花节。","梦里砧声浑末歇，那更乱蛩悲咽。","尘生燕子空楼，抛残弦索床头。","一样晓风残月，而今触绪添愁。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-70","tags":[]},{"id":"poem-bc316a4e64aca3d589ce69a7","title":"阻雨不得归瀼西甘林","author":"杜甫","dynasty":"唐","verses":["三伏适已过，骄阳化为霖。","欲归瀼西宅，阻此江浦深。","坏舟百版坼，峻岸复万寻。","篙工初一弃，恐泥劳寸心。","伫立东城隅，怅望高飞禽。","草堂乱悬圃，不隔昆仑岑。","昏浑衣裳外，旷绝同层阴。","园甘长成时，三寸如黄金。","诸侯旧上计，厥贡倾千林。","邦人不足重，所迫豪吏侵。","客居暂封殖，日夜偶瑶琴。","虚徐五株态，侧塞烦胸襟。","焉得辍两足，杖藜出岖嵚。","条流数翠实，偃息归碧浔。","拂拭乌皮几，喜闻樵牧音。","令儿快搔背，脱我头上簪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-50b39f91-4d82-4166-b291-d73be5d35733","tags":[]},{"id":"poem-bc4a3f65b7f55ce981fbd50d","title":"一落索·春风吹断前山雨","author":"向子𬤇","dynasty":"宋","verses":["春风吹断前山雨。","行云归去。","暂来须信本无心，回首了无寻处。","欲问个中玄路。","阿谁能语。","澄江霁月却深知，把此意、都分付。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-166","tags":[]},{"id":"poem-bc4e4bea922dedf620c42054","title":"题王氏清轩","author":"华镇","dynasty":"宋","verses":["开亭后圃号清轩，非逐豪华效兔园。","入座馨香惟蕙草，照窗清浅只池源。","暂来自怪尘埃远，竟日原无鸟雀喧。","况是绕垣多翠竹，春风次第长龙孙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-df2966c4-e643-46f0-88b5-a975edd39208","tags":[]},{"id":"poem-bc58b1381deb9ac39585ee3b","title":"蝃𬟽","author":"佚名","dynasty":"先秦","verses":["蝃𬟽在东，莫之敢指。女子有行，远父母兄弟。","朝𬯀于西，崇朝其雨。女子有行，远兄弟父母。","乃如之人也，怀婚姻也。大无信也，不知命也！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-50","tags":[]},{"id":"poem-bc5bcf05ee5afd6f62764c7b","title":"赠别空公","author":"马戴","dynasty":"唐","verses":["云门秋却入，微径久无人。","后夜中峰月，空林百衲身。","寂寥寒磬尽，盥漱瀑泉新。","履迹谁相见，松风扫石尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b53c4ba8-1bdd-4c32-b18b-33bc14cef2fc","tags":[]},{"id":"poem-bc5dc42bfe79858abef03b15","title":"幽州未得授戒","author":"义存","dynasty":"唐","verses":["一十出家未是时，二十出家正是时。","今遇官坛缘未合，𨀁踵且作老沙弥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5c6c567c-326e-47a5-886a-35373db65bbc","tags":[]},{"id":"poem-bc615357c3b85db5a6e8d080","title":"咏史诗 杜邮","author":"胡曾","dynasty":"唐","verses":["自古功成祸亦侵，武安冤向杜邮深。","五湖烟月无穷水，何事迁延到陆沈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6d19a214-2fe2-4d97-8847-f2aa4e0eb652","tags":[]},{"id":"poem-bc64182fe67b1f4fda42b597","title":"浄名  其一","author":"米芾","dynasty":"宋","verses":["厌市冲烟入，忘怀对客迟。","吟看飞鸟没，坐到夕阳时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-030147f9-a6b3-4b26-b8f4-a62d200d3f0e","tags":[]},{"id":"poem-bc821647b44e9d5c5df3fa4f","title":"小师智潮请赞","author":"释了惠","dynasty":"宋","verses":["㑃无讨处，强无讨处。","刚道太虚空，纯是生铁铸。","人言养子不及父，殊不知扬子江心有个郭璞墓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f781bca7-cd70-4021-9e35-f8a2a1b0a002","tags":[]},{"id":"poem-bc88263449ee8357c7bc7331","title":"同茅郎中使君送河南裴文学","author":"孟郊","dynasty":"唐","verses":["河南有归客，江风绕行襟。","送君无尘听，舞鹤清瑟音。","菱蔓缀楚棹，日华正嵩岑。","如何谢文学，还起会云吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-310c962f-32b2-4f23-b973-59235cdf6fec","tags":[]},{"id":"poem-bc88878e50ad8087b02d30bd","title":"题庾楼","author":"张栻","dynasty":"宋","verses":["南瞻庐阜北淮山，下有长江万顷寒。","往事无边随去浪，西风有客傍阑干。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d5a6c08c-ca77-418c-88a6-4884ffdc5ebb","tags":["长江"]},{"id":"poem-bca3c402c7bd282880ccd5f4","title":"扬州","author":"鲜于侁","dynasty":"宋","verses":["金山一拳石，出髻如溟涨。","天外辨两潮，江南分列嶂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-22724889-a6c5-49e0-a1e3-2167e98a8ba3","tags":[]},{"id":"poem-bca4b89459e71b14beb2a154","title":"花犯·小娉婷","author":"吴文英","dynasty":"宋","verses":["小娉婷，清铅素靥，蜂黄暗偷晕。","翠翘敧鬓。","昨夜冷中庭，月下相认。","睡浓更苦凄风紧。","惊回心未稳。","送晓色、一壶葱茜，才知花梦准。","湘娥化作此幽芳，凌波路，古岸云沙遗恨。","临砌影，寒香乱、冻梅藏韵。","熏炉畔、旋移傍枕，还又见、玉人垂绀鬒。","料唤赏、清华池馆，台杯须满引。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-191","tags":["宋词三百首"]},{"id":"poem-bca590c3c0340def5957f5ba","title":"路旁草","author":"徐夤","dynasty":"唐","verses":["楚甸秦原万里平，谁教根向路傍生。","轻蹄绣毂长相蹋，合是荣时不得荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3c1efd5a-19b5-4bf9-9fcf-7c9b46d2d342","tags":[]},{"id":"poem-bca78be35f03f2633cf07206","title":"蕙兰芳引·寒莹晚空","author":"周邦彦","dynasty":"宋","verses":["寒莹晚空，点清镜、断霞孤鹜。","对客馆深扃，霜草未衰更绿。","倦游厌旅，但梦绕、阿娇金屋。","想故人别后，尽日空疑风竹。","塞北氍毹，江南图障，是处温燠。","更花管云笺，犹写寄情旧曲。","音尘迢递，但劳远目。","今夜长，争奈枕单人独。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-410","tags":[]},{"id":"poem-bcaae350e9ac8c843b17b382","title":"南吕/玉交枝","author":"杨景贤","dynasty":"元","verses":["贪杯无厌，每日价汛流霞潋滟。","子云嘲谑防微渐，托鸱夷彩笔拈。","季鹰好饮豪兴添，忆莼鲈只为葡萄酽。","倒玉山恁般瑕玷，又不是周晏相沾。","糟腌着葛仙翁，曲埋那张孝廉。","恣狂情，谁与砭？英雄尽你夸，富贵饶他占，则这黄垆畔有祸殃，玉缸边多危险，酒呵，播声名天下嫌。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2339","tags":[]},{"id":"poem-bcac90583ac65b491b420c70","title":"广惠寺","author":"蔡清臣","dynasty":"宋","verses":["云中老树冷萧萧，溪上僧归倚画桡。","谁为秋风乘兴去，松窗先听富阳潮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-ab0dfd11-6435-40f8-b234-c2c97508ab28","tags":[]},{"id":"poem-bcb415c3fdd081c1b717732b","title":"荷叶杯·绝代佳人难得","author":"韦庄","dynasty":"五代","verses":["绝代佳人难得，倾国，花下见无期。","一双愁黛远山眉，不忍更思惟。","闲掩翠屏金凤，残梦，罗幕画堂空。","碧天无路信难通，惆怅旧房栊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-43","tags":[]},{"id":"poem-bcb9d8a6934ae4e04dde063c","title":"句 二","author":"李昪","dynasty":"唐","verses":["朱扉尽日镇长扃。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0165065e-7689-4c78-b797-82a1d49a1eaa","tags":[]},{"id":"poem-bcbc033853320448a6d91566","title":"阆州东楼筵奉送十一舅往青城县得昏字","author":"杜甫","dynasty":"唐","verses":["曾城有高楼，制古丹雘存。","迢迢百余尺，豁达开四门。","虽有车马客，而无人世喧。","游目俯大江，列筵慰别魂。","是时秋冬交，节往颜色昏。","天寒鸟兽休，霜露在草根。","今我送舅氏，万感集清尊。","岂伊山川间，回首盗贼繁。","高贤意不暇，王命久崩奔。","临风欲恸哭，声出已复吞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e3553a22-2323-4926-a694-752c3481e2a5","tags":[]},{"id":"poem-bcdf7f9f0555fd038c8bb7b3","title":"与韩愈李翺张籍话别","author":"孟郊","dynasty":"唐","verses":["朱弦奏离别，华灯少光辉。","物色岂有异，人心顾将违。","客程殊未已，岁华忽然微。","秋桐故叶下，寒露新雁飞。","远游起重恨，送人念先归。","夜集类饥鸟，晨光失相依。","马迹遶川水，雁书还闺闱。","常恐亲朋阻，独行知虑非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7c52da8e-5d6b-48bf-baf3-6d0c5851907e","tags":[]},{"id":"poem-bce02b5f1542cd422ce6b341","title":"九日送人","author":"李嘉祐","dynasty":"唐","verses":["晴景应重阳，高台怆远乡。","水澄千室倒，雾卷四山长。","受节人逾老，惊寒菊半黄。","席前愁此别，未别已沾裳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-11df3b79-9086-4902-840b-c9e9adf9fc25","tags":[]},{"id":"poem-bce770ee024f9755ccbe59e3","title":"摘得新·酌一卮","author":"皇甫松","dynasty":"唐","verses":["酌一卮，须教玉笛吹。","锦筵红蜡烛，莫来迟。","繁红一夜经风雨，是空枝。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-22","tags":[]},{"id":"poem-bd00b1fd661dacbcada16837","title":"妾薄命","author":"张籍","dynasty":"唐","verses":["薄命妇，良家子，无事从军去万里。","汉家天子平四夷，护羌都尉裹尸归。","念君此行为死别，对君裁缝泉下衣。","与君一日为夫妇，千年万岁亦相守。","君爱龙城征战功，妾愿青楼歌乐同。","人生各各有所欲，讵得将心入君腹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fa247c16-f33d-427b-ba30-20a1cd152f54","tags":[]},{"id":"poem-bd03925c91c8b94318f0d8aa","title":"江城子·恩重娇多情易伤","author":"韦庄","dynasty":"五代","verses":["恩重娇多情易伤，漏更长，解鸳鸯。","朱唇未动，先觉口脂香。","缓揭绣衾抽皓腕，移凤枕，枕潘郎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-2","tags":[]},{"id":"poem-bd061174814b46ff9fcb5238","title":"奉送严大夫再领容府二首 二","author":"曹唐","dynasty":"唐","verses":["日照双旌射火山，笑迎宾从却南还。","风云暗发谈谐外，感会潜生气概间。","蕲竹水翻台榭湿，刺桐花落管弦闲。","无因得靸真珠履，亲从新侯定八蛮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d6a6bdae-51a9-4f5a-903a-ac72b298e06e","tags":[]},{"id":"poem-bd0807e3533cb3b7cb797a0d","title":"短歌行 其一","author":"曹操","dynasty":"汉","verses":["对酒当歌，人生几何！譬如朝露，去日苦多。","慨当以慷，忧思难忘。何以解忧？唯有杜康。","青青子衿，悠悠我心。但为君故，沉吟至今。","呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。","明明如月，何时可掇？忧从中来，不可断绝。(明明一作：佼佼)。","越陌度阡，枉用相存。契阔谈䜩，心念旧恩。(谈䜩一作：谈宴)。","月明星稀，乌鹊南飞。绕树三匝，何枝可依？","山不厌高，海不厌深。周公吐哺，天下归心。(海一作：水)。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-1","tags":[]},{"id":"poem-bd100a195b90e9b0a1137c65","title":"闻蝉","author":"来鹄","dynasty":"唐","verses":["绿槐阴里一声新，雾薄风轻力未匀。","莫道闻时总惆怅，有愁人有不愁人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c5acc0ee-6f84-4905-a0ec-791cf855d91a","tags":[]},{"id":"poem-bd11beb141d567dabaaa6233","title":"羽调排歌","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生)愚蠢孙华，情偏意迷，全亏家有贤妻。","(旦)今朝兄弟共怡怡，堪笑乔人枉用机。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1961","tags":[]},{"id":"poem-bd12bac488356467fb9c6182","title":"浣溪沙·碧户珠窗小洞房","author":"毛滂","dynasty":"宋","verses":["碧户珠窗小洞房。","玉醅新压嫩鹅黄。","半青橙子可怜香。","风露满帘清似水，笙箫一片醉为乡。","芙蓉绣冷夜初长。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-736","tags":[]},{"id":"poem-bd15ab2bc9d341c795bbea16","title":"天仙子·坐治吴州成乐土","author":"张先","dynasty":"宋","verses":["坐治吴州成乐土。","诏卷风飞来圣语。","亲舆乞得便藩归，瑶席主。","杯休数。","清夜为君歌白苎。","花接旧枝新蕊吐。","造化不知人有助。","看花岁岁比甘棠，嘉月暮。","东门路。","只恐带将春色去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-356","tags":[]},{"id":"poem-bd16ad6d2ed227f604d1fe12","title":"思平泉树石杂咏一十首 二猿","author":"李德裕","dynasty":"唐","verses":["钓濑水涟漪，富春山合沓。","松上夜猿鸣，谷中清响合。","冲网忽见羁，故山从此辞。","无由碧潭饮，争接绿萝枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-edcec266-bb0e-463e-a84c-849192e218a9","tags":[]},{"id":"poem-bd27d6ae70a2d7917616f2dc","title":"题杨秘书新居","author":"张籍","dynasty":"唐","verses":["爱闲不向争名地，宅在街西最静坊。","卷里诗过一千首，白头新受秘书郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-72f904c4-5ff2-419a-b3a4-b96dcc2b89cc","tags":[]},{"id":"poem-bd30d269b910499b3a49b2d7","title":"易水怀古","author":"马戴","dynasty":"唐","verses":["荆卿西去不复返，易水东流无尽期。","落日萧条蓟城北，黄沙白草任风吹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-72586e99-f113-4d0d-9f16-6015c4e7da47","tags":[]},{"id":"poem-bd3cf7d0698f2c03548fd4c6","title":"金精山","author":"孙勰","dynasty":"宋","verses":["多病厌凡垢，思欲求道真。","金精古福地，中有超世人。","驾言从之游，洗我千劫尘。","洞门无扃锁，松竹四时春。","泉声散风韵，珩珮若有闻。","九微何燿煜，百和方氤氲。","稽首愿乞灵，缥缈如相亲。","至妙非言说，萧然清吾神。","大道本自然，一悟不在勤。","逍遥此岩下，当自观其身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0d527d26-0cee-44f8-a5c7-87a49d3be3c3","tags":[]},{"id":"poem-bd42a51ba9deabb2931036b0","title":"七弟兄","author":"杨景贤","dynasty":"元","verses":["我钻在这壁，那壁，没安我这死身己。","滚将一个碌碡在根底，脚踏着才得见真实，百般打扮千般戏。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10111","tags":[]},{"id":"poem-bd444695b40c35f9751bf43d","title":"题案上诗（题拟）","author":"任赞","dynasty":"唐","verses":["数年叨内署，衫色俨然倾。","任赞字希度，知君是火精。","（见《类说》卷五四《玉堂闲话》。","）（〖1〗《玉堂闲话》：「梁朝翰林学士任赞居职数年，犹着朱绂，于案上题诗。","梁主知之，命赐紫袍金章。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b62355a5-50af-4abe-b6e4-479b585f4efc","tags":[]},{"id":"poem-bd4abd9028905b725e3e077a","title":"献令狐相公时相公郊坛行事回","author":"项斯","dynasty":"唐","verses":["鹗在卿云冰在壶，代天才业本𬣙谟。","荣同伊陟传朱户，秀比王商入画图。","昨夜星辰回劒履，前年风月满江湖。","不知机务时多暇，还许诗家属和无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5b6adf15-e83c-419f-85ae-0a274d353d00","tags":[]},{"id":"poem-bd50630a7d60aea33b96756f","title":"寄赠许璋少府","author":"姚鹄","dynasty":"唐","verses":["若说君高道，何人更得如。","公庭唯树石，生计是琴书。","诗句峭无敌，文才清有余。","不知尺水内，争滞北溟鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-693778c0-81f5-4fa1-97a3-a53246b99651","tags":[]},{"id":"poem-bd523d8556b803c2c1a12f35","title":"城南即事  其六","author":"张栻","dynasty":"宋","verses":["枕边风雨过今春，起步园林已绿阴。","更向坡头望湘浦，水云无际遶遥岑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-06e294c2-58be-40b8-86de-3a53c8e0f355","tags":[]},{"id":"poem-bd56049faef176596eec256f","title":"小长干曲","author":"崔国辅","dynasty":"唐","verses":["月暗送潮风，相寻路不通。","菱歌唱不彻，知在此塘中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-861898e7-b6b0-4805-9bc4-a6b6a1ca55a0","tags":[]},{"id":"poem-bd583922af103a2adda5a58f","title":"再次韵示师文","author":"陈造","dynasty":"宋","verses":["中年多病刚制酒，文字讥评慵挂口。","克家尚须狮子子，时踞风林一哮吼。","藏山有书当衣钵，端能太史牛马走。","之齐莫操竽，名楚要穿柳。","未闻狗监荐子虚，聊遣吴王质非有。","独无鼓吹娱乃公，胜日不应长袖手。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-825ce66a-0982-4e5c-a264-230a7dce7876","tags":[]},{"id":"poem-bd58ccfbc8001b23658b59e3","title":"杂曲歌辞 行路难三首 二","author":"李白","dynasty":"唐","verses":["大道如青天，我独不得出。","羞逐长安社中儿，赤鸡白狗赌梨栗。","弹劒作歌奏苦声，曳裾王门不称情。","淮阴市井笑韩信，汉朝公卿忌贾生。","君不见昔时燕家重郭隗，拥篲折腰无嫌猜。","剧辛乐毅感恩分，输肝剖胆效英才。","昭王白骨萦蔓草，谁人更扫黄金台。","行路难，归去来。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e12edd83-36cd-4e8a-a630-91874631c51f","tags":["唐诗三百首","乐府","失意","叹息"]},{"id":"poem-bd5c4d909ae82a43821517fd","title":"逢入京使","author":"岑参","dynasty":"唐","verses":["故园东望路漫漫，双袖龙钟泪不干。","马上相逢无纸笔，凭君传语报平安。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-07238ad9-c348-43d4-b1d7-25d89369286d","tags":["唐诗三百首","生活","边塞","初中古诗","七言绝句","思乡","七年级下册(课外)"]},{"id":"poem-bd5d83b5b24b41e4fa967fa3","title":"颂古六首  其三","author":"释士珪","dynasty":"宋","verses":["劈面三拳，连腮七掌。","尽大地人，不知痛痒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6c9c4617-8b05-4999-976a-49e96e54ced7","tags":[]}];
